(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{})["2chr"]={"1":{"1":"Соломон, сын Давида, утвердился на престоле. Господь, его Бог, был с ним и весьма его возвеличил.","2":"Обратился Соломон ко всему Израилю – начальникам тысяч и сотен, судьям, ко всем вождям Израиля, главам родов, –","3":"и отправился во главе всех собравшихся к Гаваонскому святилищу. Там находился Божий Шатер Встречи, сделанный в пустыне рабом Господа Моисеем.","4":"Хотя Давид уже перенес ковчег Божий из Кирьят – Иеарима на предназначенное для него место (ведь Давид поставил для него шатер в Иерусалиме),","5":"там, перед скинией Господней, еще находился медный жертвенник, который сделал Бецалел, сын Ури, сына Хура. Соломон и все собравшиеся поклонились Господу.","6":"Соломон поднялся к медному жертвеннику, стоявшему перед Шатром Встречи, пред лицом Господа, и принес тысячу всесожжении.","7":"Следующей ночью Бог явился Соломону и сказал: «Проси у Меня, что хочешь».","8":"Соломон ответил Богу: «Ты оказывал моему отцу Давиду великие милости и после него возвел на престол меня.","9":"Так пусть, Господи Боже, исполнится обещание, которое Ты дал моему отцу Давиду! Ты поставил меня царем над народом, многочисленным, как пыль земная.","10":"Так даруй мне мудрость и разумение, чтобы я верно поступал с этим народом. Кому под силу править Твоим великим народом?!»","11":"Бог сказал Соломону: «За то, что именно таким было твое желание, за то, что просишь ты не богатства, не сокровищ, не славы, не смерти твоих врагов, даже долголетия не просишь, а просишь мудрости и разумения, чтобы управлять Моим народом, над которым Я поставил тебя в цари, –","12":"будут тебе даны и мудрость, и разумение; а к тому и богатство, и сокровища, и славу Я дам тебе, каких не бывало у царей до тебя, да и после тебя не будет».","13":"Соломон возвратился в Иерусалим от святилища в Гаваоне, от Шатра Встречи. Соломон стал царствовать над Израилем.","14":"Он создал колесничное и конное войско: колесниц у него было тысяча четыреста, а конницы – двенадцать тысяч. Он разместил их в крепостях, специально отведенных для колесничного войска, а также у себя в Иерусалиме.","15":"В правление Соломона золота и серебра было в Иерусалиме – что камней, кедра – что сикоморов в Предгорье.","16":"Лошадей Соломону доставляли из Египта и из Куэ: царские купцы покупали их в Куэ.","17":"Колесница, доставленная из Египта, обходилась в шестьсот шекелей серебра, а лошадь – во сто пятьдесят шекелей. Затем купцы поставляли их всем хеттским и арамейским царям."},"2":{"1":"Соломон приказал построить Храм для имени Господа и царский дворец.","2":"Он назначил семьдесят тысяч носильщиков, восемьдесят тысяч каменотесов в горных каменоломнях, и над ними поставил три тысячи шестьсот надзирателей.","3":"Соломон отправил послов к Хураму, царю Тира, чтобы передать ему следующее: «Прежде ты помогал моему отцу Давиду, отправляя ему кедровые бревна, из которых он построил себе дворец.","4":"Теперь я строю Храм для имени Господа, моего Бога, чтобы воскурять пред Ним благовония, приносить регулярные хлебные приношения и совершать всесожжения – утром и вечером, в субботы, новолуния и в дни, назначенные Господом, нашим Богом, как навеки заповедано Израилю.","5":"Храм, который я начал строить, будет великим, ведь и Бог наш превосходит величием всех других богов.","6":"Но как же построить Храм для Него, если небеса и даже небеса небес не могут вместить Его? И кто я такой, чтобы строить для Него дом? Разве только то место, где Ему будут совершаться воскурения.","7":"Поэтому пошли мне человека, который владеет искусством работы по золоту, по серебру, по меди и по железу, разбирается в пурпурных, багряных и яхонтовых тканях и в ремесле резчика, чтобы он присоединился к умельцам, которые есть у меня в Иудее и Иерусалиме – тем, которых назначил мой отец Давид.","8":"И еще пошли мне с Ливанских гор кедров, кипарисов и деревьев альгум, ведь я знаю, что среди твоих людей есть те, кто умеет рубить ливанский лес. А я добавлю к ним и своих людей,","9":"чтобы заготовить множество древесины – ведь Храм, который я начал строить, будет великим и чудесным.","10":"Твоим дровосекам, которые будут валить лес, я предоставлю двадцать тысяч коров пшеницы, двадцать тысяч коров ячменя, двадцать тысяч батов вина и двадцать тысяч батов оливкового масла».","11":"Хурам, царь Тира, ответил Соломону в письме: «По любви к Своему народу Господь поставил тебя царем над этим народом!»","12":"А далее Хурам писал: «Благословен Господь, Бог Израиля, создавший небо и землю, даровавший царю Давиду мудрого сына, который обладает проницательностью и разумом и который построит Господень Храм и царский дворец!","13":"Я отправляю к тебе мудрого и сведущего человека, Хурам – Ави .","14":"Мать его происходит из племени Дана, а отец – житель Тира. Он владеет искусством работы по золоту, по серебру, по меди и по железу, разбирается в строительстве из камней и древесины, в пурпурных, яхонтовых и багряных тканях и тонком льняном полотне, во всевозможной резьбе и в любой искусной работе, которая будет доверена ему. Он будет работать вместе с твоими умельцами и умельцами моего господина, царя Давида.","15":"Посылай своим слугам пшеницу, ячмень, масло и вино, о которых ты, мой господин, говорил.","16":"А мы будем рубить на Ливанских горах деревья, какие тебе будут нужны, и сплавлять их в виде плотов по морю до Яффы, а оттуда ты сможешь перевозить их в Иерусалим».","17":"Соломон провел перепись всех переселенцев, какие были в Израиле (как прежде делал его отец Давид). Их оказалось сто пятьдесят три тысячи шестьсот.","18":"Семьдесят тысяч из них он сделал носильщиками, восемьдесят тысяч – каменотесами в горных каменоломнях, а три тысячи шестьсот – надзирателями, которые заставляли людей работать."},"3":{"1":"Соломон начал строить Храм Господень в Иерусалиме, на горе Мориа, где Господь явился отцу его Давиду, в месте, которое подготовил Давид, – на гумне Орнана – евусея.","2":"Соломон начал строительство во второй месяц четвертого года своего царствования.","3":"Такое основание заложил Соломон для Божьего Храма: шестьдесят локтей в длину (в локтях старого размера) и двадцать локтей в ширину.","4":"Притвор перед Храмом был двадцать локтей в длину (такой же была ширина всего Храма), а в высоту – сто двадцать локтей. Изнутри Соломон выложил его чистым золотом.","5":"Большой зал он облицевал древесиной кипариса и покрыл изнутри чистым золотом, а сверху сделал украшения в виде пальм и цепочек.","6":"Соломон украсил зал драгоценными камнями и золотом, настоящим Парваимским золотом.","7":"В том зале он обложил золотом и балки, и пороги, и стены, и двери. На стенах он вырезал изображения херувимов.","8":"Также Соломон построил зал святыни святынь. Его длина соответствовала ширине Храма – двадцать локтей, и в ширину он был тоже двадцать локтей. Соломон облицевал его чистым золотом, которого потребовалось шестьсот талантов,","9":"а на гвозди ушло пятьдесят шекелей золота. Верхние комнаты он тоже обложил золотом.","10":"В зале святыни святынь Соломон сделал двух херувимов, вырезанных из дерева; их тоже покрыли золотом.","11":"Общая длина их крыльев составляла двадцать локтей: у первого херувима одно крыло, длиной в пять локтей, касалось стены Храма, а другое, длиной тоже в пять локтей, касалось крыла второго херувима.","12":"И у второго херувима одно крыло, длиной в пять локтей, касалось стены Храма, а другое, длиной тоже в пять локтей, соприкасалось с крылом первого херувима.","13":"Таким образом, крылья были распростерты на двадцать локтей. Сами херувимы стояли на ногах, лицом к Храму.","14":"Еще Соломон соткал завесу из яхонтовой, пурпурной, багряной пряжи и тончайшего льна и изобразил на ней херувимов.","15":"Перед Храмом он воздвиг две колонны высотой по тридцать пять локтей, каждую венчала капитель высотой в пять локтей.","16":"Вершины колонн он украсил цепочками, к цепочкам прикрепил сто гранатов.","17":"Эти колонны Соломон поставил у входа в Храм с правой и левой стороны. Ту, что справа, он назвал Яхин, а ту, что слева – Боаз."},"4":{"1":"Соломон сделал медный жертвенник длиной в двадцать локтей, шириной в двадцать локтей и высотой в десять локтей.","2":"Соломон изготовил Море – литое, круглое; в десять локтей от края до края; высота его – пять локтей; окружность, если мерить шнурком, – тридцать локтей.","3":"В нижней его части, по кругу, шли изображения быков. Они опоясывали все Море (в десять локтей размером), двумя рядами, и были отлиты вместе с Морем, как единое целое.","4":"Море покоилось на двенадцати быках. Три быка смотрели на север, три – на запад, три – на юг, три – на восток, крупы их были обращены внутрь, а Море лежало на них сверху.","5":"Толщина стенки Моря – одна ладонь; край его был как край чаши, в виде цветка лотоса. Море вмещало три тысячи батов.","6":"Соломон сделал десять чанов и поставил их по пять с правой и левой стороны. В них омывали то, что шло на всесожжение, а в Море омывались священники.","7":"Соломон сделал десять золотых светильников по всем правилам и поставил их в Храме по пять с правой и левой стороны;","8":"он изготовил десять золотых столов, которые тоже поставил в Храме по пять с правой и левой стороны; а также сто чаш для кропления кровью.","9":"Соломон устроил Двор священников и Большой внутренний двор, в который вели двери, отделанные медью.","10":"Море он установил с правой стороны, к юго – востоку от Храма.","11":"Хурам изготовил котлы, лопатки и чаши для кропления кровью. Он завершил все работы, которые выполнял для царя Соломона в Храме Божьем:","12":"две колонны; две капители в виде чаш на вершинах колонн; две плетенки, покрывающие чашевидные капители на вершинах колонн;","13":"четыреста гранатовых плодов на двух плетенках (по два ряда плодов на каждой из плетенок, покрывающих чашевидные капители колонн).","14":"Он сделал подставки и чаны, стоящие на подставках;","15":"одно медное Море; двенадцать быков, поддерживающих медное Море;","16":"котлы, лопатки, вилки. Всю эту утварь для царя Соломона, строившего Господень Храм, Хурам – Ави изготовил из полированной меди.","17":"(Царь отливал их в Иорданской долине, в Ави - Хаадама, между Суккотом и Цередой.)","18":"Соломон сделал этой утвари великое множество, и меди на нее пошло без счета.","19":"И еще изготовил Соломон другую утварь для Божьего Храма: золотой жертвенник; столы для хлеба, что должен лежать пред лицом Господа;","20":"светильники с лампадами, которые зажигают, как положено, у входа в святилище, – тоже из чистого золота;","21":"цветки, лампады, щипцы – все из золота, причем самого лучшего;","22":"ножницы, чаши для кропления кровью, ложки для благовоний, жаровни из чистого золота. И даже внутренние двери, ведущие в святыню святынь, и двери храмового зала – тоже были из золота."},"5":{"1":"Завершив все работы по строительству Храма Господа, царь Соломон перенес туда дары, которые его отец Давид посвятил Господу – серебро и золото и прочую утварь – и поместил их в сокровищницу Храма Божьего.","2":"И вот созвал Соломон старейшин Израиля, всех глав племен и вождей родов израильских к себе, в Иерусалим, чтобы вынести ковчег договора с Господом из Города Давидова (Город Давидов – это Сион).","3":"Все израильтяне собрались к царю на праздник, это был седьмой месяц года.","4":"Когда пришли все старейшины Израиля, левиты подняли ковчег","5":"и понесли. И ковчег Господень, и шатер Встречи, и всю священную утварь, что была в шатре – все это понесли левиты – священники.","6":"А царь Соломон и вся община Израиля, созванная им, приносили перед ковчегом в жертву столько баранов и быков, что не счесть их было, не пересчитать.","7":"Священники поставили ковчег договора с Господом в назначенном ему месте, в святилище Храма, в святыне святынь, под сенью крыл херувимовых.","8":"Херувимы простирали крылья над местом, где находился ковчег, осеняя ковчег и шесты для ношения ковчега.","9":"Шесты ковчега были такими длинными, что их торчащие концы были видны, если стать перед внутренним святилищем; но снаружи они не были видны. Так ковчег расположен и доныне.","10":"В ковчеге не было ничего, кроме двух каменных табличек, которые положил туда Моисей на Хориве, когда Господь заключил договор с израильтянами, ушедшими из Египта.","11":"И вот священники стали выходить из святилища (все собравшиеся там священники, к какому бы из подразделений они ни относились, предварительно освятили и очистили себя).","12":"Все левиты – певцы – и Асаф, и Хеман, и Иедутун вместе со своими сыновьями и родичами – в одеждах из тонкого льняного полотна стояли с кимвалами, лирами и арфами к востоку от жертвенника, и с ними стояли сто двадцать священников, которые трубили в трубы.","13":"Звуки труб сливались с пением, единым звучанием прославляя и восхваляя Господа. И вот, когда возгласили трубы, тарелки и все музыкальные инструменты, а певцы запели хваление Господу: «Он благ, навеки милость Его!» – тогда весь Храм Господень наполнился облаком!","14":"И священники не могли находиться пред облаком и продолжать свою службу: это Слава Господня наполнила собой Храм Божий."},"6":{"1":"Затем Соломон сказал: «Во мгле Господь пожелал обитать!","2":"Дворец высокий Тебе я возвел – жилище, где Ты пребудешь вовек!»","3":"Повернувшись лицом к общине Израиля – вся община Израиля стояла перед ним – царь благословил ее","4":"и сказал: «Благословен Господь, Бог Израиля! Ныне исполнил Он то, что обещал отцу моему, Давиду. Господь говорил:","5":"„С тех пор как Я вывел народ Мой из Египта, не избрал Я во владениях племен Израилевых ни одного города, в котором будет построен Храм для имени Моего, и не избрал Я никого правителем Моего народа, Израиля.","6":"Ныне же Я избираю Иерусалим – чтобы там пребывало имя Мое, и избираю Давида – править народом Моим\".","7":"Мой отец Давид захотел построить Храм для имени Господа, Бога Израилева,","8":"но Господь сказал моему отцу Давиду: „Ты хочешь построить Храм для имени Моего – это ты хорошо задумал.","9":"Но построишь его не ты, а твой сын, зачатый тобою – вот кто построит Храм для имени Моего\".","10":"И вот Господь исполнил Свое обещание: я наследовал отцу моему Давиду и воссел на престоле израильском, по слову Господа; я построил Храм для имени Господа, Бога Израилева,","11":"и поместил в нем ковчег, где хранится договор с Господом, который заключил Он с сынами Израилевыми».","12":"Затем Соломон в присутствии всей общины Израиля стал перед жертвенником Господа и воздел руки –","13":"а в середине двора Соломон сделал медный помост в пять локтей длиной, в пять локтей шириной и в три локтя высотой – и вот, став на него, Соломон в присутствии всей общины Израиля пал на колени, про – стер руки к небу","14":"и сказал: «Господи, Боже Израилев! Нет бога, равного Тебе, ни на небе, ни на земле! Ты соблюдаешь договор с рабами Твоими и хранишь верность тем, кто служит Тебе всем сердцем.","15":"Ты верен обещанию, которое дал рабу Твоему Давиду, отцу моему: что изрек Ты Своими устами, то ныне исполнил рукой Своей.","16":"Будь же, Господь, Бог Израиля, и впредь верен обещаниям, которые Ты дал рабу Твоему Давиду, отцу моему. Ты сказал ему: „Твои потомки никогда не будут отторгнуты от лица Моего, всегда будут на престоле Израиля, если только они будут соблюдать Закон Мой, если будут служить Мне, как ты Мне служил\".","17":"Господь, Бог Израилев! Пусть сбудутся Твои слова, которые Ты возвестил рабу Твоему Давиду, моему отцу.","18":"Поистине, Богу ли жить на земле с людьми?! Небеса и небеса небес не могут вместить Тебя – тем более этот дом, что я построил.","19":"Услышь молитву раба Твоего и прошение его, Господи, Боже мой! Услышь вопль и молитву, которую раб Твой воссылает пред Тобою ныне!","20":"Да будут очи Твои взирать на этот Храм и днем, и ночью – на это место, в котором, Ты обещал, пребудет имя Твое; и да услышишь Ты всякую молитву, с которой раб Твой сюда обратится.","21":"Услышь всякое прошение раба Твоего и народа Твоего Израиля: сюда будут они обращаться с молитвами, а Ты услышь их из Своей небесной обители – услышь и помилуй!","22":"Если кто будет обвинен в грехе против ближнего и от него потребуется принести клятву, и он поклянется перед Твоим жертвенником в этом Храме –","23":"услышь с небес и рассуди рабов Твоих. Пусть обратится зло на злодея и воздастся ему по делам его, пусть станет явной правда правого и воздастся ему за праведность его.","24":"Если народ Твой Израиль будет разбит врагом в сражении, за то, что согрешил пред Тобою, но потом покается, и восславит Твое имя, и будет молиться Тебе и просить Тебя в этом Храме –","25":"услышь с небес эту молитву, прости грех народа Твоего Израиля, возврати их в страну, которую Ты дал отцам их и им самим.","26":"Если затворятся небеса и не будет дождя, за то, что сыны Израилевы согрешили пред Тобою, и они обратятся сюда с молитвами, и восславят Твое имя, и покаются в грехах своих, за которые Ты их караешь –","27":"услышь с небес эту молитву, прости грех Твоих рабов – народа Твоего Израиля, и укажи им путь, по которому они должны идти, и ниспошли дождь на землю Твою, которую Ты дал Своему народу во владение.","28":"И если случится в стране голод, если случится мор, если погибнет хлеб от суховея или спорыньи, если налетит саранча, если враг осадит город – какая бы беда и напасть ни случились,","29":"о чем бы ни молил Тебя, о чем бы ни просил Тебя кто-нибудь из народа Твоего Израиля, в скорби и страдании простирая руки к этому Храму,","30":"услышь его молитву с небес, где Ты пребываешь, и помилуй! Воздай каждому по делам его, зная, что у кого на сердце, – ведь один лишь Ты знаешь, что на сердце у человека.","31":"И пусть они боятся и почитают Тебя, идут по Твоему пути всю жизнь, живя на земле, которую Ты даровал отцам нашим.","32":"И даже если чужеземец, не принадлежащий к народу Твоему Израилю, придет из дальней страны ради Твоего великого имени, ради руки Твоей мощной, десницы простертой – если придет он помолиться к этому Храму,","33":"то услышь его с небес, из вечного жилища Твоего, и исполни все, о чем он попросит. Пусть все народы земли познают имя Твое, пусть они боятся и почитают Тебя так же, как Тебя почитает народ Твой Израиль, и пусть знают, что именем Твоим осенен этот Храм, мною построенный.","34":"Если народ Твой пойдет на войну против врагов – туда, куда Ты его поведешь, – и будет молиться Господу, обратясь лицом к городу, который Ты избрал, и к Храму, который я построил для имени Твоего, –","35":"то услышь с небес их молитву и прошение, будь им заступником.","36":"Если же они согрешат пред Тобою (ведь нет человека, который бы не грешил!) и, прогневавшись на них, Ты отдашь их в руки врагов, и уведут их в плен, угонят в страну далекую или близкую, –","37":"и если там, в той стране, где они будут в плену, они всем сердцем раскаются, – если там, в стране тех, кто пленил их, они вернутся к Тебе, станут Тебя умолять и скажут: „Согрешили мы, преступны мы и виновны\", –","38":"если там, в стране своих врагов, угнавших их в плен, они обратятся к Тебе всем сердцем и всей душою и станут молиться Тебе, обратясь лицом к стране, которую Ты дал их отцам, к городу, который Ты избрал, и к Храму, который я построил для имени Твоего, –","39":"услышь тогда с небес, из Твоего жилища, их молитву и прошение! Будь им заступником. Прости народ Твой, который согрешил пред Тобою.","40":"Боже мой! Обрати Свой взор, прислушайся к молитвам, возносимым на этом месте!","41":"Восстань, о Господи Боже, и войди в место обитания Твоего – Ты и могучий Твой ковчег! Да облекутся во спасение Твои священники, и верные да возрадуются доброте Твоей!","42":"Господи Боже, не отвергни Своего помазанника, не оставь Своей милостью раба Твоего Давида!»"},"7":{"1":"Когда Соломон окончил свою молитву, с небес сошел огонь и поглотил всесожжение и другие жертвы. Слава Господня наполнила Храм.","2":"Священники не могли войти в Храм Господень, потому что его наполнила слава Господня.","3":"Все израильтяне, увидев, как сошел огонь и слава Господня наполнила Храм, пали на колени и простерлись ниц, воздавая Господу хвалу: «Он благ, навеки милость Его!»","4":"Царь и весь народ совершили жертвоприношения Господу.","5":"Царь Соломон принес в жертву двадцать две тысячи быков и сто двадцать тысяч баранов. Так царь и весь народ торжественно освятили Божий Храм.","6":"Священники выполняли свои обязанности, левиты играли на музыкальных инструментах Господних, которые сделал царь Давид, чтобы восхвалять Господа, словами восхвалений Давидовых: «Навеки милость Его!» Священники, стоя перед левитами, трубили в трубы; при этом присутствовали все израильтяне.","7":"Соломон освятил место посреди двора перед Храмом Господа – он принес там жертвы всесожжения и жир пиршественных жертв (ведь сделанный Соломоном медный жертвенник не мог вместить такого всесожжения, такого хлебного приношения и жира этих пиршественных жертв).","8":"Тогда Соломон устроил семидневное празднество. Весь Израиль – великое множество народу – собрался отовсюду, от Лево - Хамата до Египетской ложбины.","9":"На восьмой день было завершение праздника. Торжества по поводу начала служения у жертвенника длились семь дней, семь дней продолжался праздник.","10":"В двадцать третий день седьмого месяца Соломон отпустил народ по домам, и все разошлись, радостные и довольные тем, как много добра сделал Господь для Давида, Соломона и для Израиля, народа Своего.","11":"Так Соломон завершил строительство Господнего Храма и царского дворца. Ему удалось выполнить все, что он задумал сделать в Господнем Храме и во дворце.","12":"Ночью Господь явился Соломону и сказал: «Я услышал твою молитву. Я избрал это место, чтобы здесь совершались жертвоприношения.","13":"Если Я затворю небеса и не будет дождя, если повелю саранче пожирать урожай, если нашлю мор на Мой народ –","14":"и если тогда Мой народ, именем Моим осененный, смирится, взмолится и устремится ко Мне, отвратившись от своих злых дел – Я услышу их с небес, прощу им грех и пошлю стране исцеление.","15":"Я обращу Свой взор, прислушаюсь к молитвам, возносимым на этом месте.","16":"Я избрал и освятил этот Храм, и Мое имя будет вечно обитать в нем; и всегда будут обращены к нему очи Мои и сердце Мое.","17":"И если ты будешь служить Мне, как служил отец твой Давид, во всем будешь поступать так, как Я тебе повелел, если будешь соблюдать Мои повеления и законы –","18":"то Я укреплю твой царский престол, согласно договору, который Я заключил с твоим отцом Давидом, сказав: „Твои потомки всегда будут на престоле Израиля\".","19":"Но если вы отступитесь, если забудете Мои повеления и законы, которые Я установил для вас, и станете служить и поклоняться другим богам,","20":"то Я изгоню вас из Моей земли, которую даровал вам, и отвергну этот Храм, который Я избрал для имени Моего. Тогда все народы будут глумиться над ним и поносить его.","21":"И тогда, как бы ни был он теперь великолепен, всякий, кто пройдет мимо, ужаснется и присвистнет, и спросит: „Отчего так обошелся Господь с этой страною и с этим Храмом?\"","22":"И ему ответят: „Оттого, что забыли они Господа, Бога своих отцов, который вывел их из Египта, и последовали за другими богами, стали поклоняться им и служить им. Вот за что обрушил на них Господь все эти беды\"»."},"8":{"1":"Двадцать лет Соломон строил Храм Господа и собственный дворец,","2":"а после этого отстроил города, которые передал ему Хурам, и поселил там израильтян.","3":"Соломон пошел в Хамат – Цову и захватил ее.","4":"Он отстроил Тадмор, что в пустыне, и все крепости со складами, которые находятся в Хамате. Юн отстроил Верхний Бет – Хорон и Нижний Бет – Хорон (сделал их крепостями со стенами и воротами на запоре),","6":"а также Баалат, и все крепости, где у Соломона были склады, и крепости для колесниц, и крепости для конницы. В Иерусалиме, и на Ливане, и по всей подвластной ему стране Соломон построил все, что задумал.","7":"На всех оставшихся хеттов, амореев, периззеев, хиввеев и евусеев – на всех неизраильтян,","8":"потомков тех, кто уцелел в этой стране, тех, кого не истребили израильтяне, – на всех них Соломон возложил трудовую повинность. Эту трудовую повинность они несут и доныне.","9":"А израильтян Соломон не принуждал к работам: они были у него воинами, начальниками стражи, колесничного войска и конницы.","10":"Вот распорядители работ, которые у Соломона управляли народом, – их было двести пятьдесят человек.","11":"Дочь фараона Соломон переселил из Города Давидова во дворец, который специально для нее построил. Он решил: «Нельзя, чтобы у меня во дворце Давида, царя Израилева, жила женщина, потому что это место свято: ковчег Господа некогда посетил его».","12":"На жертвеннике Господнем, который находился перед притвором Храма, Соломон совершал всесожжения Господу","13":"во все дни, когда это требовалось по установлению Моисея – по субботам, в новолуния и трижды в год в определенное время: на праздник Пресного хлеба, на праздник Недель и на праздник Шалашей.","14":"В соответствии с установлением своего отца Давида, Соломон ввел разделение священников по различным служениям, распределил левитов в соответствии с их обязанностями – они должны были совершать восхваления и прислуживать священникам, как положено на каждый день; разделил стражей, расставив их по всем воротам. Ведь так повелел Давид, человек Божий.","15":"Все повеления царя относительно священников и левитов были в точности исполнены, включая и те, что касались сокровищницы.","16":"Так Соломон завершил строительство – он заложил основание Господнего Храма, он его и достроил. Храм Господень был полностью завершен.","17":"Кроме того, Соломон отправился в Эцион – Гевер и в Элот на берегу моря, в стране Эдом.","18":"Хурам велел, чтобы его люди отправили Соломону корабли и опытных моряков. Вместе с людьми Соломона они приплыли в страну Офир и привезли оттуда четыреста пятьдесят талантов золота, которые доставили царю Соломону."},"9":{"1":"Слух о Соломоне достиг царицы Савской, и она пришла в Иерусалим испытать Соломона загадками, пришла с огромным караваном – с верблюдами, навьюченными благовониями, несметным количеством золота и драгоценными камнями. Пришла она к Соломону и говорила с ним обо всем, о чем хотела.","2":"Но о чем бы она ни спросила, Соломон отвечал ей – не было такого вопроса, который был бы неясен для царя и на который он не мог бы ей ответить.","3":"Узнала царица Савская, какая у Соломона мудрость, увидала, какой Храм он построил,","4":"и что подают у него за столом, и как рассаживаются его приближенные, увидела слуг, прислуживающих ему, и как они одеты, виночерпиев и как они одеты, и какие всесожжения приносит он в Храме Господа – и дух у нее захватило.","5":"Так сказала она царю: «Значит, правду слышала я у себя в Саве о твоих деяниях и твоей мудрости.","6":"Я не верила слухам, но теперь пришла и своими глазами вижу – мне не рассказали и половины о твоей великой мудрости! Ты превосходишь все, что я о тебе слышала.","7":"Счастливы твои люди; счастливы твои приближенные, что они всегда рядом с тобою и внимают твоей мудрости!","8":"Благословен Господь, твой Бог, который по благоволению Своему посадил тебя на Свой престол, сделал тебя царем, чтобы ты служил Господу, своему Богу. По Своей любви к Израилю, желая укрепить его навеки, Бог твой поставил тебя царем над Израилем, чтобы ты творил правду и суд!»","9":"Она подарила царю сто двадцать талантов золота, несметное множество благовоний и драгоценные камни. Невиданные благовония привезла царица Савская в дар царю Соломону!","10":"А слуги Хурама вместе со слугами Соломона привозили золото из Офира, привозили дерево альгум и драгоценные камни.","11":"Из дерева альгум Соломон сделал пандусы в Господнем Храме и в царском дворце, а также арфы и лиры для музыкантов. Ничего подобного не было во всей Иудее.","12":"Соломон подарил царице Савской все, что она только пожелала и что только попросила, и это еще помимо ответных даров. И отправилась она вместе со своей свитой в обратный путь, в свою страну.","13":"Ежегодно к Соломону поступало шестьсот шестьдесят шесть талантов золота,","14":"не считая того, что выплачивали ему торговцы и купцы, и золота и серебра, поступавших Соломону от всех царей Аравии и от наместников.","15":"Царь Соломон сделал двести больших щитов, обитых золотом (на каждый такой щит пошло по шестьсот шекелей золота),","16":"и триста малых щитов (на каждый такой щит пошло по триста шекелей золота). Эти щиты царь поместил в Зале Ливанского Леса.","17":"Еще Соломон сделал большой трон из слоновой кости, обитый чистым золотом.","18":"У этого трона было шесть ступеней, золотое подножие, а с обеих сторон от сиденья – подлокотники, подле которых стояло по льву.","19":"А на шести ступенях стояло двенадцать львов, по одному на каждой ступени с каждой стороны. Ничего подобного не бывало ни в одном царстве!","20":"А кубки у царя Соломона были все золотые, и вся утварь Зала Ливанского Леса была из чистого золота, а серебро во времена Соломона не ставили ни во что.","21":"Ведь у царя были корабли, которые ходили в Таршиш (вместе с людьми Хурама). Каждые три года привозили таршишские корабли золото, серебро, слоновую кость, обезьян и павлинов.","22":"Соломон превзошел всех царей земли богатством и мудростью.","23":"Все цари земли жаждали увидеть Соломона и послушать ту мудрость, которую вложил ему в сердце Бог.","24":"Приходя к Соломону, они приносили ему дары: серебряные и золотые изделия, одеяния, оружие, благовония, коней и мулов – и так из года в год.","25":"У Соломона было четыре тысячи лошадиных упряжек и колесниц, а конницы – двенадцать тысяч. Он разместил их в крепостях, специально отведенных для колесничного войска, а также у себя в Иерусалиме.","26":"Соломону подвластны были все цари от Великой Реки до страны филистимлян, вплоть до границы Египта.","27":"В его правление серебра в Иерусалиме было – что камней, а кедров – что сикоморов в Предгорье.","28":"Лошадей Соломону доставляли из Египта и со всего света.","29":"А все прочее о Соломоне от начала до конца описано в Деяниях пророка Нафана, в пророчестве Ахии из Силома и в видении провидца Иеддо об Иеровоаме, сыне Невата.","30":"Сорок лет правил Соломон в Иерусалиме, царствуя надо всем Израилем.","31":"Соломон почил с предками и был похоронен в Городе Давидовом. Царем после него стал Рехавам, его сын."},"10":{"1":"Рехавам отправился в Шехем: там собрались все израильтяне, чтобы провозгласить его царем.","2":"Когда об этом услышал Иеровоам, сын Невата, то он возвратился из Египта, куда он бежал от царя Соломона.","3":"За ним послали и позвали его. Иеровоам пришел вместе со всеми израильтянами, и они сказали Рехаваму:","4":"«Твой отец придавил нас тяжким ярмом. Сделай нашу работу полегче, облегчи ярмо, что наложил на нас твой отец, – и мы будем служить тебе». –","5":"«Приходите через три дня», – ответил Рехавам. Народ разошелся.","6":"Царь Рехавам стал советоваться со старыми придворными, которые окружали его отца Соломона, пока тот был жив: «Что посоветуете, – спросил он их, – какой ответ дать народу?»","7":"Они сказали: «Если будешь обходиться с народом по – доброму, говорить с ними обходительно и ласково – эти люди станут тебе рабами на всю жизнь».","8":"Но Рехавам не внял совету стариков и стал советоваться с молодыми придворными, со своими ровесниками, которые его окружали.","9":"«Что посоветуете, – спросил он их, – какой ответ дать народу? Они меня просят: „Облегчи ярмо, которое наложил на нас твой отец\"».","10":"Молодые придворные, его ровесники, сказали: «Вот что ответь народу. Они говорят: „Твой отец наложил на нас тяжкое ярмо, облегчи его\". А ты им ответь так: „Да мой мизинец потолще отцовской ляжки!","11":"Ярмо отца было для вас тяжелым? Мое будет еще тяжелее. Отец порол вас плетьми? А я буду пороть вас кнутами\"».","12":"Иеровоам и все израильтяне пришли к Рехаваму на третий день (ведь царь так и велел им: «приходите на третий день»).","13":"Царь говорил сурово; не послушался он совета стариков","14":"и отвечал народу так, как советовали молодые: «Ярмо отца было для вас тяжелым? Мое будет еще тяжелее. Отец порол вас плетьми? А я буду пороть вас кнутами».","15":"Не послушался царь народа: такова уж была воля Бога, чтобы исполнилось слово, которое Господь возвестил Иеровоаму, сыну Невата, через Ахию из Силома.","16":"Увидели израильтяне, что царь их не послушал, и сказали ему: «Кто нам теперь Давид? Нет нам дела до сына Иессеева! Расходись по домам, Израиль! Займись собственным домом, Давид!» И все израильтяне разошлись по домам.","17":"А Рехавам стал царствовать над сынами Израилевыми, живущими в Иудее.","18":"Царь Рехавам послал к израильтянам Хадорама, надзирателя за трудовой повинностью, но израильтяне насмерть забросали его камнями. Сам царь Рехавам еле успел вскочить на колесницу, чтобы бежать в Иерусалим.","19":"С тех пор отпал Израиль от дома Давида."},"11":{"1":"Когда Рехавам прибыл в Иерусалим, то собрал из иудеев и вениамитян сто восемьдесят тысяч лучших воинов. Они должны были идти войной на Израиль и вернуть Рехаваму царскую власть.","2":"Тогда Шемае, человеку Божьему, было слово Господа:","3":"«Скажи Рехаваму, сыну Соломона, царю Иудеи, и всем сынам Израилевым из племен Иуды и Вениамина:","4":"„Так говорит Господь: не ходите воевать с вашими братьями, расходитесь по домам. Что случилось – то случилось по Моей воле!\"» Услышали они слово Господа и не пошли на Иеровоама войной.","5":"Когда Рехавам жил в Иерусалиме, он отстроил города Иудеи, сделал их крепостями.","6":"Он отстроил Вифлеем, Этам, Текоа,","7":"Бет – Цур, Сохо, Адуллам,","8":"Гат, Марешу, Зиф,","9":"Адораим, Лахиш, Азеку ,","10":"Цору, Айялон и Хеврон, сделал их крепостями на землях Иуды и Вениамина.","11":"Он укрепил оборонительные сооружения, назначил начальников, создал там запасы продовольствия, масла и вина,","12":"разместил щиты и копья во всех городах. Он очень хорошо укрепил города – Иуда и Вениамин были его владениями.","13":"Священники и левиты, жившие по всему Израилю, отовсюду собрались к Рехаваму.","14":"Левиты даже бросали свои пастбища и владения, чтобы переселиться в Иудею, в Иерусалим, потому что Иеровоам и его сыновья не давали им служить Господу.","15":"Иеровоам назначил священников, чтобы они служили в капищах, служили козлищам и тельцам, которых он сам же и сделал.","16":"Но во всех израильских племенах находились такие люди, которые от всего сердца стремились служить Господу, Богу Израиля, – и они, вслед за левитами, отправлялись в Иерусалим, чтобы приносить жертвы Господу, Богу своих отцов.","17":"Они укрепили Иудейское царство и усилили власть Рехавама, сына Соломона, на три года, потому что в течение этих трех лет они шли по пути Давида и Соломона.","18":"Рехавам взял в жены Махалат, отцом которой был Иеримот, сын Давида, а матерью – Авихаиль, дочь Элиава, сына Иессея.","19":"Она родила ему сыновей: Иеуша, Шемарию и Захама.","20":"Еще Рехавам взял в жены Мааху, дочь Авессалома, и она родила ему Авию, Аттая, Зизу и Шеломита.","21":"Рехавам любил Мааху, дочь Авессалома, больше всех остальных жен и наложниц, а всего у него было восемнадцать жен и шестьдесят наложниц. Они родили ему двадцать восемь сыновей и шестьдесят дочерей.","22":"Рехавам назначил Авию, сына Маахи, первым среди братьев и наследником царского престола.","23":"Мудрым решением он разослал своих сыновей в разные части Иуды и Вениамина по крепостям, обеспечивая их припасами в изобилии и дав им жен."},"12":{"1":"Когда царство Рехавама усилилось и сам он утвердился на престоле, он и вместе с ним весь Израиль оставили Закон Господень.","2":"За то, что они совершили преступление против Господа, в пятый год царствования Рехавама египетский царь Шешонк пошел войной на Иерусалим.","3":"Его войско – тысяча двести колесниц, шестьдесят тысяч всадников и бесчисленное множество пришедших с ним из Египта ливийцев, суккийцев и кушитов –","4":"овладело крепостями в Иудее и дошло до Иерусалима.","5":"Тогда пришел пророк Шемая к Рехаваму и вельможам Иудеи, которые, спасаясь от Шешонка, собрались в Иерусалим, и сказал: «Так говорит Господь: вы оставили Меня – и Я оставляю вас на произвол Шешонка».","6":"Тогда иудейские вельможи и царь смиренно сказали: «Господь справедлив!»","7":"Господь увидел их смирение и сказал Шемае так: «Раз они смирились, Я не стану их губить и вскоре дарую им избавление. Моя ярость не уничтожит Иерусалим руками Шешонка.","8":"Однако они станут его слугами, чтобы они узнали, в чем разница между служением Мне и служением земным царям».","9":"Египетский царь Шешонк вступил в Иерусалим и захватил сокровища Храма Господа и сокровища царского дворца – забрал все, что там было. Взял он и золотые щиты, сделанные Соломоном.","10":"Вместо них царь Рехавам сделал медные щиты и вверил их начальникам стражников, которые охраняли вход во дворец.","11":"Всякий раз, как царь шествовал в Храм Господа, стражники, сопровождавшие его, шли с этими щитами, а после складывали их у себя, в своем помещении.","12":"И царь смирился, поэтому Гнев Господень не пал на него и не погубил его полностью – ведь в Иудее было и что-то хорошее.","13":"Царь Рехавам утвердился на престоле в Иерусалиме и царствовал. Сорок один год был Рехаваму, когда он стал царем. Семнадцать лет он царствовал в Иерусалиме – городе, который Господь выбрал из всех владений племен Израилевых, чтобы там обитало имя Его. Матерью Рехавама была Наама - аммонитянка.","14":"Он творил зло, потому что он не посвятил себя тому, чтобы следовать Господу.","15":"Деяния Рехавама от начала до конца описаны в Деяниях пророка Шемаи и в родословных записях провидца Иддо. Война между Рехавамом и Иеровоамом никогда не прекращалась.","16":"Рехавам почил с предками и был похоронен в Городе Давидовом. Царем после него стал его сын Авия ."},"13":{"1":"В восемнадцатый год царствования Иеровоама царем Иудеи стал Авия.","2":"Он правил в Иерусалиме три года. Его мать – Мааха, дочь Уриэла из Гивы . Между Авией и Иеровоамом была война.","3":"Начал войну Авия, в его войске было четыреста тысяч богатырей, отборных воинов. Иеровоам выставил против него восемьсот тысяч лучших богатырей.","4":"Авия поднялся на вершину горы Цемараим, что в Ефремовом нагорье, и оттуда обратился с речью: «Слушайте меня, Иеровоам и весь Израиль!","5":"Вам хорошо известно, что Господь, Бог Израиля, отдал израильское царство Давиду и его потомкам – по договору, навек хранимому солью!","6":"Иеровоам, сын Невата, который был на службе у Соломона, сына Давида, восстал против своего господина.","7":"Вокруг него собрались оборванцы и негодяи и одолели Рехавама, сына Соломона, который был слишком молод и нерешителен, чтобы дать им отпор.","8":"Вы задумали противостоять царству Господа, царству, которое отдано потомкам Давида! Вас великое множество, с вами золотые тельцы, которых Иеровоам сделал вашими богами.","9":"Священников, потомков Аарона, и левитов вы прогнали и, как другие народы земли, сами назначаете себе священников. Кто приведет с собой молодого бычка и семь баранов, тот и становится священником лжебогов.","10":"А наш Бог – Господь! Мы не отступились от Него, у нас служат Господу священники, потомки Аарона, и левиты выполняют предписанное.","11":"Каждое утро и каждый вечер они приносят Господу всесожжения и совершают воскурения. Они возлагают хлеба на стол из чистого золота и каждый вечер зажигают золотые лампы на светильнике. Да, мы совершаем служение Господу, нашему Богу, а вы оставили Его!","12":"Наш предводитель – Бог, Его священники трубят в трубы – раздается боевой клич на горе вам! Израильтяне, не сражайтесь с Господом, Богом ваших отцов, не будет вам в этом успеха!»","13":"Иеровоам послал часть войска в обход, чтобы незаметно выйти в тыл противнику. Сам он стоял перед иудейским войском, а в тылу его устроил засаду.","14":"Иудеи обернулись и увидели, что на них нападают и спереди, и сзади – и тогда они стали взывать к Господу. Священники затрубили в трубы,","15":"а иудеи разом издали боевой клич. И когда иудеи издали клич, Бог силами иудейского войска во главе с Авией нанес поражение Иеровоаму и всем израильтянам.","16":"Иудеи обратили израильтян в бегство, Господь отдал израильтян в руки иудеев.","17":"Так Авия во главе своего народа разгромил израильтян: пятьсот тысяч отборных израильских воинов пало в бою.","18":"Израильтяне тогда смирились, а иудеи показали свою силу, потому что искали помощи у Господа, Бога отцов их.","19":"Авия погнался за Иеровоамом и захватил у него несколько городов: Бет – Эль, Иешану и Эфрон вместе с селениями вокруг них.","20":"При Авие Иеровоам так и не восстановил силы. Господь поразил его, и он умер.","21":"Авия же укрепил свою власть. У него было четырнадцать жен, двадцать два сына и шестнадцать дочерей.","22":"Прочее об Авие, его слова и дела, описаны в рассказе пророка Иддо."},"14":{"1":"Авия почил с предками и был похоронен в Городе Давидовом. Царем после него стал его сын Аса. При нем в течение десяти лет в стране был мир.","2":"Аса творил добро и поступал так, как было угодно Господу, Богу его.","3":"Чужие жертвенники и капища он разрушил, священные камни разбил, дерева Ашеры срубил.","4":"Он велел иудеям поклоняться Господу, Богу их отцов, и исполнять Закон и заповеди Его.","5":"Во всех поселениях Иудеи он запретил капища и кумирни. При Асе покой был в царстве Иудейском.","6":"Пользуясь мирным временем, он построил осадные укрепления в городах Иудеи. В те годы никто с ним не воевал, потому что Господь даровал ему мирную жизнь.","7":"Он сказал иудеям: «Давайте отстроим эти города! Обнесем их стеной, воздвигнем башни и ворота с запорами. Страна еще в нашей власти, потому что мы почитаем Господа, Бога нашего почитаем – и Он даровал нам повсюду мирную жизнь». Иудеи отстроили города и процветали.","8":"В войске Асы было триста тысяч воинов из племени Иуды, вооруженных большими щитами и копьями, двести восемьдесят тысяч из племени Вениамина, вооруженных малыми щитами и луками. Все они были могучими воинами.","9":"На них пошел войной кушит Зерах, в его войске было тысяча тысяч воинов и триста колесниц. Когда он достиг Мареши,","10":"ему навстречу выступил Аса и выстроил свое войско для сражения в долине Цефата около Мареши.","11":"И Аса воззвал к Господу, Богу своему: «Господи, никто, кроме Тебя, не сможет помочь, когда столкнется слабый с могучим! Так помоги нам, Господи Боже наш! Мы к Тебе обращаемся за подмогой и к имени Твоему, Господи, Боже наш, прибегаем перед этими полчищами. Ведь человек Тебе не помеха!»","12":"И Господь сделал так, что Аса и иудеи нанесли поражение кушитам и обратили их в бегство.","13":"Аса со своим войском преследовал их до Герара. Кушиты понесли такие потери, что не смогли оправиться – вот какое поражение потерпели они от Господа и Его войска. Иудеи же захватили богатую добычу","14":"и уничтожили все поселения вокруг Герара – ужас Господень поразил их жителей. Все эти поселения иудеи разграбили, много добра унесли.","15":"Потом они разорили стойбища пастухов и, захватив множество баранов и верблюдов, вернулись в Иерусалим."},"15":{"1":"Дух Господа сошел на Азарию, сына Одеда,","2":"и он отправился к Асе и сказал ему: «Слушайте меня, Аса и все люди племен Иуды и Вениамина! Господь с вами, пока вы с Ним, и если вы почитаете Его, то и Он открывается вам. Но если вы оставите Его, Он тоже оставит вас.","3":"Долгое время не было в Израиле ни истинного Бога, ни священника – учителя, ни Закона.","4":"Тогда люди в бедствии своем обратились к Господу, Богу Израиля, стали просить Его о помощи – и Он открылся им.","5":"В те времена небезопасно было путешествовать, великий ужас охватил жителей всех стран.","6":"Народы уничтожали друг друга, города уничтожали друг друга. Это Бог приводил их в смятение, насылая беду за бедой!","7":"Но вы будьте тверды и не опускайте рук, ведь будет вам награда за ваши дела!»","8":"Когда Аса услышал эти пророческие слова, произнесенные Азарией, сыном пророка Одеда, то набравшись смелости, он уничтожил все мерзости в земле Иуды и Вениамина и в городах, которые он захватил на Ефремовых горах. Он обновил жертвенник Господень, который был перед притвором Храма Господа,","9":"осле этого он собрал племена Иуды и Вениамина, а также тех из племен Ефрема, Манассии и Симеона, кто жил тогда среди них – многие из Израильского царства перебегали под власть Асы, видя, что Господь, Бог, его с ним.","10":"Они собрались в Иерусалиме в третий месяц пятнадцатого года царствования Асы.","11":"В тот день они принесли в жертву Господу скот, захваченный на войне: семьсот быков и семь тысяч баранов,","12":"и вступили в договор с Господом, Богом своих отцов, обещая почитать Его всем сердцем и всей душой,","13":"а всякого, кто не будет почитать Господа, Бога Израиля, предавать смерти, будь то молодой или старик, мужчина или женщина.","14":"Они произнесли клятву Господу, сопровождая ее громкими криками и торжественными звуками труб и рогов.","15":"Все иудеи поклялись с радостью и от всего сердца. Они устремились к Господу, и Он открыл им Себя. Господь повсюду даровал им мирную жизнь.","16":"Даже Мааху, свою мать, царь Аса лишил положения царицы, за то, что она велела изготовить омерзительную Ашеру. Аса срубил эту мерзость и сжег, стер ее в пыль у ручья Кедрон.","17":"Капища по – прежнему стояли в Израиле. Но Аса всю жизнь был сердцем предан Богу.","18":"Он поместил в Божий Храм дары, которые его отец и он сам посвятили Господу: серебро, золото и храмовую утварь.","19":"Первые тридцать пять лет царствования Асы не было войны."},"16":{"1":"На тридцать шестой год его царствования Баша, царь Израиля, начал войну с Иудеей и стал укреплять крепость Раму, чтобы никто не мог ни проехать во владения Асы, царя Иудеи, ни выехать оттуда.","2":"Тогда Аса взял серебро и золото из сокровищниц Господнего Храма и из дворцовых сокровищниц и отправил его Бен – Хададу, царю арамеев, правителю Дамаска, велев передать ему:","3":"«Мы с тобой союзники, союзниками были наши отцы. Это серебро и золото я посылаю тебе в дар. Расторгни союз с Башой, царем Израиля, чтобы он отступил от моих владений».","4":"Бен – Хадад согласился с царем Асой и отправил своих полководцев в поход на израильские города. Они захватили города Ийон, Дан, Авел – Маим и крепости со складами в земле Неффалима.","5":"Узнав об этом, Баша перестал укреплять Раму, бросив начатую работу.","6":"Царь Аса собрал всех иудеев, чтобы они унесли из Рамы камни и бревна, которые Баша использовал для строительства крепости. Из них царь Аса построил крепости Геву и Мицпу .","7":"Тогда к иудейскому царю Асе пришел провидец Ханани и сказал: «Ты обратился за помощью к арамейскому царю, а не к Господу, своему Богу, – за это войско арамейского царя смогло избежать твоей руки.","8":"Могучее войско кушитов и ливийцев со множеством колесниц и всадников – даже его Господь предал в твои руки, когда ты обратился к Нему!","9":"Очи Господни видят всю землю, Он укрепляет тех, кто верен Ему всем сердцем. А ты поступил глупо и отныне обрек себя на войны».","10":"Аса разозлился на провидца и даже посадил его в темницу – так сильно прогневили его эти слова. И другие люди пострадали тогда от Асы.","11":"Все деяния Асы от начала до конца записаны в Книге царей Иудеи и Израиля.","12":"На тридцать девятом году своего царствования Аса заболел. Тяжелая болезнь поразила его ноги, но даже в таком положении он обратился не к Господу, а к врачам.","13":"Когда Аса почил с предками – а он умер на сорок первом году своего царствования –","14":"его похоронили в Городе Давидовом, в усыпальнице, которую он заранее приготовил для себя. Его положили на ложе, полное благовоний и разных благоуханных масел, и на похоронах его устроили большой костер."},"17":{"1":"После него воцарился его сын Иосафат. Он укрепил свою власть над всем Израилем.","2":"Он направил войска в укрепленные города Иудеи и поставил наместников по всей земле иудейской и в городах племени Ефрема, которые захватил его отец Аса.","3":"Господь был с Иосафатом, потому что тот поступал подобно тому, как его отец поступал в начале правления: не поклонялся Ваалам,","4":"а почитал Бога отца своего, соблюдал Его заповеди – не то что израильтяне!","5":"Господь упрочил его власть. Все иудеи платили Иосафату дань, и был он весьма богат и славен.","6":"Он всем сердцем стремился следовать Господу и еще он очистил Иудею от капищ и дерев Ашеры.","7":"На третий год своего царствования Иосафат отправил своих приближенных: Бен – Хаила, Авдия, Захарию, Нетанэла и Михея – учить народ в городах Иудеи.","8":"С ними были и левиты: Шемая, Нетания, Зевадия, Асаил, Шемирамот, Ионафан, Адония, Товия и Тов – Адония, а также священники Элишама и Иорам.","9":"Они стали учить иудеев по книге Закона Господнего – обходили все иудейские города и учили там народ.","10":"Все царства, что окружали Иудею, боялись Господа и потому не затевали войну с Иосафатом.","11":"Филистимляне платили ему дань серебром, арабы приводили ему скот: семь тысяч семьсот баранов и семь тысяч семьсот козлов.","12":"Иосафат становился все более и более могущественным. Он построил в Иудее крепости и города со складами,","13":"в городах Иудеи он начал строительство. В Иерусалиме он расположил лучших воинов.","14":"Вот их список в соответствии с делением на роды. Из племени Иуды там были начальники тысячных отрядов: Адна во главе трехсот тысяч могучих воинов;","15":"Иехоханан во главе двухсот восьмидесяти тысяч;","16":"Амасия, сын Зихри, во главе двухсот тысяч могучих воинов (он добровольно вызвался служить Господу).","17":"Из племени Вениамина: могучий воин Эльяда во главе двухсот тысяч воинов, вооруженных луками и щитами;","18":"Иозавад во главе восьмидесяти тысяч воинов.","19":"Они состояли на службе у царя, помимо тех войск, что царь разместил в укрепленных городах по всей Иудее."},"18":{"1":"Иосафат стал весьма богат и славен. Он породнился с Ахавом","2":"и через некоторое время отправился к нему в Самарию. Ахав заколол для него и его людей множество быков и баранов и подговаривал его напасть на Рамот Галаадский.","3":"Ахав, царь Израиля, спросил Иосафата, царя Иудеи: «Пойдешь со мной на Рамот Галаадский?» Тот ответил: «Куда ты, туда и я. Мое войско идет за твоим войском, вместе с тобой пойдем в бой».","4":"И еще Иосафат сказал царю Израиля: «Сперва вопроси Господа».","5":"Царь Израиля собрал четыре сотни пророков и спросил их: «Идти ли нам войной на Рамот Галаадский или не ходить?» – «Иди, – отвечали они, – Бог предаст его в руки царя!»","6":"Иосафат спросил: «А нет ли еще какого-нибудь пророка Господнего, через которого мы могли бы вопросить Господа?»","7":"Царь Израиля ответил Иосафату: «Есть еще один человек, через которого можно вопросить Господа. Но не люблю я его: он никогда не пророчит мне ничего хорошего, всегда одни беды. Это Михей, сын Имлы». На это Иосафат сказал: «Не пристало царю так говорить».","8":"Тогда царь Израиля подозвал одного евнуха и сказал: «Скорее приведи Михея, сына Имлы».","9":"На площади у ворот Самарии сидели на тронах в полном царском облачении царь Израиля и Иосафат, царь Иудеи, а все пророки в исступлении пророчествовали перед ними.","10":"Седекия, сын Кенааны, приделал себе железные рога и возглашал: «Так говорит Господь: этими рогами ты забодаешь арамеев, изничтожишь их!»","11":"И все остальные пророки предрекали то же самое. «Иди на Рамот Галаадский! – говорили они. – Удача с тобой! Господь предаст его в руки царя!»","12":"Посланец, которому велено было позвать Михея, сказал ему: «Все пророки в один голос сулят царю удачу. Хорошо бы и твое пророчество было таким же, как их пророчество. Хорошо бы и ты предрек удачу».","13":"Михей ответил: «Клянусь Господом, я скажу только то, что откроет мой Бог».","14":"Когда Михей пришел к царю, царь спросил у него: «Михей, идти нам войною на Рамот Галаадский или нет?» Он ответил: «Идите, удача с вами, будут они отданы в ваши руки!»","15":"Царь сказал ему: «Сколько же раз я буду тебя заклинать: говори мне правду и только правду, во имя Господа!»","16":"И тот ответил: «Я видел: все израильское войско по горам рассеяно, словно овцы без пастуха. И сказал Господь: „Нет у них хозяина, пусть расходятся по домам, пока живы\"».","17":"«Говорил же я тебе, – сказал царь Израиля Иосафату, – он никогда не пророчит мне ничего хорошего, всегда одни беды».","18":"А Михей продолжал: «Слушайте слово Господа! Я видел Господа: Он восседал на престоле, и все воинство небесное стояло по правую и по левую руку от Него.","19":"Господь спросил: „Кто одурачит Ахава, царя израильского, чтобы он пошел в поход и пал в Рамоте Галаадском?\" Каждый предлагал свое.","20":"Выступил вперед один дух, предстал пред Господом, и сказал: „Я его одурачу!\" Господь спросил: „Как?\"","21":"Тот ответил: „Я отправлюсь к нему и стану духом лжи в устах всех его пророков\". И Господь промолвил: „Да, тебе удастся одурачить его. Иди, делай, как сказал\".","22":"Так вот, смотри – в уста этих твоих пророков Господь послал духа лжи. Господь решил тебя погубить!»","23":"Седекия, сын Кенааны, подошел к Михею и ударил его по щеке, сказав: «По какой же это дороге дух Господа меня покинул и стал говорить с тобой?»","24":"Михей ответил: «Придет день, узнаешь. И тогда забьешься в самый дальний угол дома, чтобы тебя не нашли». –","25":"«Возьмите Михея, – приказал царь Израиля, – отведите его к Амону, градоначальнику, и Иоасу, царскому сыну,","26":"и передайте им: „Так говорит царь: бросьте его в темницу, и пусть сидит на хлебе и воде, пока я не вернусь с войны живым\"».","27":"Михей ответил: «Если ты действительно вернешься благополучно, значит, не Господь говорил через меня. Слушайте, все народы!»","28":"Царь Израиля и Иосафат, царь Иудеи, выступили в поход на Рамот Галаадский.","29":"«Я пойду на бой переодетым, – сказал царь Израиля Иосафату, – а ты оставайся в своих царских одеждах». Царь Израиля надел чужую одежду и бросился в бой.","30":"А царь арамеев приказал начальникам своих колесничных отрядов: «Не вступайте в бой ни с командирами, ни с рядовыми – только с царем Израиля».","31":"Когда начальники арамейских колесничных отрядов увидели Иосафата, то решили, что это и есть царь Израиля, и устремились к нему, чтобы сразиться с ним. Иосафат воззвал к Богу о помощи, и Господь спас его, Бог увел его от преследователей.","32":"Начальники колесничных отрядов увидели, что это не царь Израиля, и повернули в другую сторону.","33":"А какой-то лучник выстрелил – и, сам того не зная, сразил царя Израиля. Стрела прошла в щель между латами. «Поворачивай, вывози меня из боя! – сказал царь. – Я ранен».","34":"Сражение в тот день было жарким. Царя израильского поддерживали, чтобы он стоял на колеснице, на виду у арамеев, но вечером, на закате того дня он умер."},"19":{"1":"А Иосафат, царь Иудеи, живым возвратился домой в Иерусалим.","2":"Навстречу царю Иосафату отправился провидец Иегу, сын Ханани, и сказал: «Ты нечестивцам помогаешь и с ненавидящими Господа водишь дружбу? За это падет на тебя гнев Господень!","3":"Впрочем, найдутся у тебя и добрые дела, ведь ты истребил по всей стране дерева Ашеры и посвятил себя служению Богу».","4":"Иосафат жил в Иерусалиме. Он снова стал объезжать свою страну, от Беэр – Шевы до Ефремовых гор, чтобы возвратить народ к Господу, Богу их отцов.","5":"Во всех укрепленных городах Иудеи, город за городом, он назначал судей","6":"и так говорил им: «Думайте, что делаете, ведь вы творите суд Господень, а не суд человеческий, Господь с вами, когда вы выносите приговоры.","7":"Бойтесь Господа, соблюдайте все строго! Ведь Господу, нашему Богу, чужды несправедливость, лицемерие и мздоимство».","8":"И в Иерусалиме Иосафат назначил судей из левитов, священников и глав израильских родов, чтобы они вершили суд Господень и разбирали тяжбы жителей Иерусалима.","9":"Он им заповедал: «Вот что вы должны делать, боясь Господа, честно и безупречно:","10":"какая бы тяжба ни поступила к вам от ваших братьев, живущих в ваших городах, – будь то дело об убийстве или о законе, о заповедях, о тех или иных установлениях и правилах – отвращайте их от греха, чтобы не пал на вас и на ваших собратьев гнев Господень. Поступайте так – и не согрешите.","11":"Верховный священник Амария пусть руководит вами во всех делах, которые касаются Господа; Зевадия, сын Измаила, глава племени Иуды – в делах, которые касаются царя, а левиты пусть помогают вам. Действуйте твердо, и да будет с вами Господь во всяком добром деле!»"},"20":{"1":"Потом пошли на Иосафата войной моавитяне и аммонитяне с меунитянами.","2":"Иосафату объявили: «Несметное полчище идет против тебя из-за моря, из Эдома. Оно уже в Хацецон – Тамаре» – то есть в Эн – Геди.","3":"Испугавшись, Иосафат решил вопросить Господа и объявил по всей Иудее пост.","4":"Иудеи собрались, чтобы просить Господа о помощи – из всех городов иудейских пришли люди, чтобы вопросить Господа.","5":"Иосафат встал перед жителями Иудеи и Иерусалима, собравшимися в Храме Господа, перед Новым двором,","6":"и сказал: «Господи, Боже отцов наших! Ты – Бог на небесах, Ты владычествуешь над царствами всех народов. В Твоей руке – сила и мощь, никому против Тебя не устоять.","7":"Боже наш! Ты изгнал жителей этой земли, отдав ее во владение Твоему народу, Израилю, – навеки даровал ее потомкам возлюбленного Твоего Авраама.","8":"Поселившись там, они построили святилище для имени Твоего. Они говорили:","9":"„Если придут к нам беды – наказание войной, мор или голод – мы встанем перед этим Храмом, перед Тобой, ведь в этом Храме пребывает имя Твое, и воззовем о нашей беде – а Ты тогда выслушай нас и спаси!\"","10":"И вот теперь аммонитяне, моавитяне и люди Сеирских гор, в земли которых Ты не дал войти израильтянам на их пути из Египта (израильтяне прошли стороной и не стали их уничтожать) –","11":"эти люди отплатили нам тем, что явились сюда изгнать нас из владений, которые Ты дал нам в удел.","12":"Боже наш! Воздай им должное! Мы не столь сильны, чтобы противостоять такому великому нашествию, и мы не знаем, что делать. К Тебе обращены наши взоры!»","13":"Все иудеи предстали перед Господом, с ними вместе были их жены и дети.","14":"И прямо посреди собрания дух Господень охватил левита Захарию, сына Бенаи, сына Иеиэла, сына Маттании из потомков Асафа,","15":"и тот стал говорить: «Внимайте, все иудеи, все жители Иерусалима, царь Иосафат! Так говорит вам Господь: не бойтесь и не страшитесь этих полчищ, ведь они сражаются не с вами, а с Богом.","16":"Завтра выступайте против них в поход. Они сейчас двигаются по подъему Циц, вы встретите их в конце долины перед Иеруэлской пустыней.","17":"Но сражаться вам не придется, стойте и смотрите, как спасет вас Господь. Иуда и Иерусалим, не бойтесь, не страшитесь, выходите завтра против них – с вами Господь!»","18":"Иосафат пал ниц, а вместе с ним поклонились Господу все иудеи и жители Иерусалима.","19":"А левиты из родов кехатитов и кореитов поднялись с колен и стали громко возносить хвалу Господу, Богу Израиля.","20":"Ранним утром они отправились к пустыне Текоа. Когда они выступили, Иосафат встал и сказал: «Слушайте меня, жители Иудеи и Иерусалима! Верьте Господу, вашему Богу, – и будете под верной защитой Его, верьте Его пророкам – и удача будет с вами».","21":"Посоветовавшись с народом, Иосафат назначил певцов, чтобы они, двигаясь впереди войска, славили Господа и святое Его величие: «Благодарите Господа, навеки милость Его!»","22":"Когда они начали свое радостное хвалебное пение, Господь послал воителей устроить засады против аммонитян, моавитян и людей Сеирских гор, которые пошли войной на Иудею, и враги были разбиты.","23":"Аммонитяне и моавитяне напали на людей Сеирских гор и полностью их уничтожили. А как только покончили с ними, сами же перебили друг друга.","24":"Когда иудеи добрались до места, с которого можно было увидеть пустыню, то стали глядеть, где же войско – а увидели только мертвые тела на земле. Никто не спасся!","25":"Иосафат со своим народом стал собирать военную добычу – они набрали множество скота, имущества, одежды и прочего добра. Они набрали столько, что не могли все унести. Так велика была добыча, что собирали ее три дня.","26":"А на четвертый день они собрались в долине Благословения и благословили там Господа – потому это место и называется так доныне: долина Благословения.","27":"Все жители Иудеи и Иерусалима во главе с Иосафатом вернулись с великим ликованием в Иерусалим – ведь Господь так их обрадовал, избавив от врагов!","28":"Войдя в Иерусалим под звуки лир, арф и труб, они направились ко Храму Господа.","29":"Цари окрестных земель стали бояться Бога, услышав, как Господь сражался с врагами Израиля.","30":"Покой настал в царстве Иосафата, его Бог даровал ему мирную жизнь повсюду.","31":"Иосафат царствовал в Иудее. Тридцати пяти лет от роду он стал царем и двадцать пять лет царствовал в Иерусалиме. Его мать – Азува, дочь Шилхи .","32":"Он во всем, никуда не отступая, следовал за своим отцом Асой, и его дела были угодны Господу.","33":"Вот только капища оставались, и народ не обратился еще полностью к Богу их отцов.","34":"А прочее об Иосафате от начала до конца описано в Деяниях Иегу, сына Ханани, которые были внесены в Книгу царей Израиля.","35":"Потом Иосафат, царь Иудеи, заключил союз с Ахазией, царем Израиля, который творил нечестие.","36":"Они договорились построить корабли, чтобы отправить их в Таршиш. Корабли были построены в Эцион – Гевере.","37":"Тогда Элиэзер, сын Додавы из Мареши, стал пророчествовать об Иосафате: «За то, что ты заключил союз с Ахазией, Господь разрушит творение твоих рук». Корабли потерпели крушение и не смогли добраться до Таршиша."},"21":{"1":"Когда Иосафат почил с предками и был похоронен вместе с предками в Городе Давидовом, вместо него воцарился его сын Иорам.","2":"У него были братья, сыновья Иосафата: Азария, Иехиэл, Захария, Азария, Михаил и Шефатия. Все они были сыновьями Иосафата, царя Израилева.","3":"Отец щедро одарил их золотом, серебром и другими дарами, дал им во владение крепости в Иудее. Царство же он передал Иораму, своему первенцу.","4":"Когда Иорам сменил своего отца на престоле и укрепил свою власть, то предал смерти всех своих братьев, а с ними и некоторых вельмож Израилевых.","5":"Когда Иорам стал царем, ему было тридцать два года. Он царствовал в Иерусалиме восемь лет.","6":"Он шел по пути царей Израиля, делал то же самое, что и весь род Ахава – ведь его жена была дочерью Ахава. Он творил дела, ненавистные Господу.","7":"Но ради договора, заключенного с Давидом, Господь решил не губить Иудею: ведь Господь пообещал Давиду, что светильник его рода не угаснет вовек.","8":"При Иораме эдомитяне восстали и вышли из-под власти Иудеи и поставили себе собственного царя.","9":"Иорам выступил против них в поход вместе со своими полководцами и колесницами. Ночью он разбил эдомитян, окруживших его вместе с его колесничными отрядами.","10":"С тех пор и доныне Эдом не подчиняется Иудее. Тогда же и Ливна восстала против власти Иорама, потому что он оставил Господа, Бога своих отцов.","11":"Он даже устраивал в иудейских городах капища – жителей Иерусалима вовлекал в блуд, иудеев сбил с пути.","12":"К нему пришло письмо от пророка Илии: «Так говорит Господь, Бог твоего предка Давида! Ты не шел по пути своего отца Иосафата и Асы, царя Иудеи,","13":"а пошел по пути израильских царей и стал вовлекать в блуд жителей Иудеи и Иерусалима, как делал это род Ахава. И своих братьев, сыновей твоего отца, которые были лучше тебя, ты убил –","14":"за это Господь обрушит великое бедствие на твой народ, твоих жен и детей, на все твое имущество.","15":"А тебя самого Он поразит изнутри тяжкой болезнью, которая будет длиться изо дня в день, пока не вывалятся твои внутренности от болезни наружу».","16":"Господь возбудил вражду к Иораму в филистимлянах и арабах, подчинявшихся кушитам.","17":"Они напали на Иудею, прорвались вглубь страны и разграбили царский дворец, а жен и детей Иорама увели в плен. Не осталось у него сыновей, кроме младшего Иоахаза.","18":"После этого Господь поразил его внутренности неизлечимой болезнью.","19":"Она длилась и длилась, а на исходе второго года внутренности вывалились от болезни наружу и он умер в страшных муках. Народ не стал зажигать в его честь костер, как зажигал в честь его предков.","20":"Иорам стал царем в возрасте тридцати двух лет и царствовал в Иерусалиме восемь лет. Никто не горевал о его смерти, он был похоронен в Городе Давидовом, но не там, где похоронены цари."},"22":{"1":"Вместо него жители Иерусалима поставили на царство его младшего сына Ахазию, потому что старшие были убиты, когда отряд, пришедший с арабами, напал на военный лагерь. Воцарился Ахазия, сын Иорама, иудейского царя.","2":"Когда Ахазия стал царем, ему было двадцать два года. Он царствовал в Иерусалиме один год. Его мать – Гофолия, из рода Омри .","3":"Он шел по пути Ахавова рода, потому что мать побуждала его к нечестивым поступкам.","4":"Он творил дела, ненавистные Господу, как и все потомки Ахава – после смерти отца они стали его советниками и привели его к гибели.","5":"Так, по их совету Ахазия двинулся вместе с Иорамом, сыном израильского царя Ахава, на Рамот Галаадский воевать с Хазаэлом, царем Арама. Но арамеи ранили Иорама.","6":"Он вернулся в Изреель залечивать раны, полученные от арамеев в Рамоте, где он сражался с Хазаэлом, царем Арама. Иудейский царь Ахазия, сын Иорама, тоже отправился в Изреель – навестить раненого Иорама, сына Ахава.","7":"Все это произошло с Ахазией по воле Господа. Когда он прибыл, они вместе с Иорамом вышли навстречу Иегу, сыну Нимши, который получил помазание Господне и должен был уничтожить дом Ахава.","8":"Иегу свершил суд над родом Ахава: сначала он выследил и убил иудейских сановников и родичей Ахазии, состоявших у него на службе;","9":"потом он стал искать самого Ахазию, и тот был схвачен в своем укрытии в Самарии – его привели к Иегу и убили. Они похоронили его, помня, что он внук Иосафата, почитавшего Господа своим всем сердцем. Среди потомков Ахазии не было никого, кто был бы способен взять царскую власть в свои руки.","10":"Когда Гофолия, мать Ахазии, узнала о смерти сына, она перебила всех наследников престола Иудеи.","11":"Но царевна Иехошева похитила Иоаса, сына Ахазии, и не дала убить его вместе с другими царевичами – спрятала его в спальне, вместе с его кормилицей. Гофолия так и не смогла его убить, так как Иехошева, дочь царя Иорама и жена священника Иехояды, спрятала ребенка (она ведь была сестрой Ахазии).","12":"Шесть лет его скрывали с ними в Храме Господа. Страной в это время правила Гофолия."},"23":{"1":"А на седьмой год Иехояда решился: он договорился с сотниками – Азарией, сыном Иерохама, Измаилом, сыном Иехоханана, Азарией, сыном Оведа, Маасеей, сыном Адаи, и Элишафатом, сыном Зихри.","2":"Они обошли Иудею и созвали из всех иудейских городов левитов и глав израильских родов. Все они собрались в Иерусалиме","3":"и там, в Храме Божьем, присягнули царю. Иехояда сказал им: «Царствовать должен царский сын! Ведь так обещал Господь о роде Давида.","4":"Вот что вы должны делать. Пусть треть тех из вас, кто заступает в эту субботу на службу, священники и левиты, служат стражами ворот,","5":"треть – несут службу у царского дворца, и треть – у ворот Основания. Весь народ в это время будет во дворе Господнего Храма.","6":"Пусть никто не входит в Господень Храм, кроме священников и левитов, прислуживающих им, – они могут входить, ведь они святы. Пусть весь народ совершает, что повелел Господь.","7":"Пусть левиты встанут вокруг царя с оружием в руках. Всякий, кто направится к Храму, будет убит. Повсюду следуйте за царем».","8":"Левиты и все иудеи исполнили все, что приказал им священник Иехояда. Все они собрались вместе со своими людьми – и те, кто в ту субботу заступал на службу, и те, кто не заступал, – священник Иехояда не позволял уйти ни одному из отрядов.","9":"Священник Иехояда выдал сотникам копья, щиты и колчаны царя Давида, хранившиеся в Божьем Храме.","10":"Он расставил вооруженных людей от южного крыла Храма до северного, а также у жертвенника и перед Храмом, чтобы охранять царя со всех сторон.","11":"Потом вывели царевича, возложили на него корону и вручили ему знаки царского достоинства. Иоаса провозгласили царем, Иехояда и его сыновья помазали его на царство, и все стали кричать «Да здравствует царь!».","12":"Услышав шум народа и стрелков, прославляющих царя, Гофолия вышла к собравшимся, к Храму Господа, –","13":"и видит, что на помосте у входа стоит царь, рядом с царем стоят военачальники, трубачи с трубами, а народ ликует и трубит в трубы, а возглавляют славословие певцы с музыкальными инструментами. И тогда, разодрав одежды, закричала Гофолия: «Измена, измена!»","14":"Священник Иехояда приказал сотникам, которые командовали отрядами: «Выведите ее за пределы Храма. Кто будет на ее стороне – убивайте». Он сказал так: «Не убивайте ее в Храме Господнем!»","15":"Гофолию схватили, отвели к тому входу во дворец, что у Конских ворот, и там убили.","16":"Священник Иехояда присягнул сам и привел народ к присяге на верность царю – чтобы народ этот был народом Господа.","17":"Потом все отправились к храму Ваала и разрушили его. Жертвенники и статуи разбили, а Маттана, Ваалова жреца, убили перед жертвенниками.","18":"Иехояда поручил Храм Господа священникам и левитам, согласно тому, как Давид распределил обязанности, поручил им совершать всесожжения в Храме Господа, приносить положенные по Моисееву Закону жертвоприношения Господу, с радостным пением, по установлениям Давида.","19":"У ворот Храма он поставил стражей ворот, не пускавших никого, кто по какой-либо причине был нечист.","20":"Иехояда, в сопровождении сотников, знатных людей, начальников и всего народа, вывел царя из Храма Господа и через Верхние ворота ввел во дворец. Иоаса возвели на царский трон.","21":"Народ ликовал, в городе воцарилось спокойствие. Гофолия уже была убита."},"24":{"1":"Cемь лет было Иоасу, когда он стал царем. Он царствовал в Иерусалиме сорок лет. Его мать – Цивья, родом из Беэр – Шевы.","2":"На протяжении всей жизни Иехояды Иоас творил дела, угодные Господу.","3":"Иехояда дал ему двух жен, и у него родились сыновья и дочери.","4":"Спустя некоторое время Иоас пожелал обновить Храм Господень.","5":"Он собрал священников и левитов и сказал им: «Ступайте скорее в города Иудеи и соберите со всех израильтян деньги на ежегодный ремонт Храма вашего Бога». Но левиты не торопились.","6":"Тогда царь позвал их начальника Иехояду и спросил его: «Почему ты не потребуешь от левитов, чтобы они собрали с Иудеи и Иерусалима подать на содержание Шатра Завета, которую установили Моисей, раб Господень, и все израильтяне?","7":"Ведь сыновья Гофолии нечестивой разорили Божий Храм и даже использовали для служения Ваалам святыни Господнего Храма!»","8":"По приказу царя был изготовлен ящик, который поместили на улице у ворот Господнего Храма.","9":"По Иудее и Иерусалиму было объявлено, что жители должны приносить Господу подать, которую Моисей, раб Божий, наложил на израильтян в пустыне.","10":"Все сановники и народ с радостью приносили деньги и опускали их в ящик, пока он не наполнялся.","11":"Когда было нужно, чтобы левиты отнесли ящик на проверку царю, или когда они видели, что денег набралось уже много, то приходили царский писец и проверяющий от первосвященника, опорожняли ящик, а затем возвращали его обратно, на прежнее место. Так они делали изо дня в день и собрали очень много денег.","12":"Царь и Иехояда передали деньги тем, кто проводил работы в Господнем Храме, и они наняли каменотесов и плотников, чтобы те обновили Храм Господа, и кузнецов и медников, чтобы те ремонтировали Храм Господа.","13":"Работники принялись за дело, и так начались восстановительные работы. Они вернули Божьему Храму его изначальный облик и укрепили его.","14":"Когда все было готово, они принесли царю и Иехояде оставшиеся деньги. На эти средства была изготовлена утварь для Господнего Храма: предметы, необходимые для служения и всесожжении, ковши, золотая и серебряная утварь. Пока Иехояда был жив, в Господнем Храме регулярно совершались всесожжения.","15":"Иехояда состарился и умер, насытившись жизнью, в возрасте ста тридцати лет.","16":"Его похоронили в городе Давидовом, рядом с царями, потому что он творил в Израиле добро, служа Богу и Его Храму.","17":"После смерти Иехояды пришли иудейские сановники поклониться царю. С тех пор он начал слушать их советы.","18":"А они, забыв о Храме Господа, Бога своих отцов, стали служить деревам Ашеры и идолам. Гнев небесный обрушился на Иудею и Иерусалим за этот грех.","19":"Господь посылал к ним пророков, чтобы обратить народ к Себе: пророки предупреждали их, но они не слушали.","20":"Дух Господа вошел в Захарию, сына священника Иехояды. Он предстал перед народом и сказал: «Так говорит Бог: почему вы нарушаете заповеди Господни? Не будет вам ни в чем удачи! Раз вы оставили Господа, то и Он оставит вас».","21":"Против Захарии составили заговор и по приказу царя его забили камнями во дворе Господнего Храма.","22":"Царь Иоас и не вспомнил о том, как верно служил ему отец Захарии, Иехояда, – и убил его сына. Умирая, тот сказал: «Пусть Господь увидит и отомстит!»","23":"В конце того же года против Иоаса выступило арамейское войско. Арамеи напали на Иудею и Иерусалим, перебили всех предводителей народа, а добычу отправили царю Дамаска.","24":"Немногочисленно было арамейское войско, но Господь отдал в их руки огромное полчище, ведь иудеи оставили Господа, Бога своих отцов. Так арамеи покарали Иоаса.","25":"Когда арамеи, оставив Иоаса всего израненного, отступили, то его приближенные сговорились отомстить ему за смерть сына священника Иехояды. Они убили его в собственной постели. Иоас умер и его похоронили в Городе Давидовом, но не там, где похоронены цари.","26":"Заговор против него составили Завад, сын аммонитянки Шимат, и Иозавад, сын моавитянки Шимрит.","27":"О его сыновьях, о множестве его деяний, про обустройство Божьего Храма написано в рассказах книги Царей. Царем после него стал Амасия, его сын."},"25":{"1":"Когда Амасия стал царем, ему было двадцать пять лет. Он царствовал в Иерусалиме двадцать девять лет. Мать его – Иоаддан, родом из Иерусалима.","2":"Деяния Амасии были угодны Господу, но не был Амасия предан Господу всем сердцем.","3":"Когда Амасия крепко взял власть в свои руки, он казнил тех вельмож, что убили его отца, царя.","4":"Но их сыновей он не казнил, ведь в Законе, в книге Моисея, написано, что Господь заповедал: «Отцов нельзя предавать смерти за вину сыновей, а сыновей – за вину отцов. Человек может быть предан смерти лишь за то преступление, которое совершил он сам».","5":"Амасия собрал всех жителей Иудеи и распределил всех иудеев и вениамитян под начальство предводителей тысячных и сотенных отрядов в соответствии с делением на роды. Были переписаны все в возрасте от двадцати лет и старше: триста тысяч пригодных к воинской службе мужчин, способных носить копье и щит.","6":"К тому же царь нанял в Израиле сто тысяч могучих воинов за сто талантов серебра.","7":"Пришел к нему человек Божий и сказал: «Царь! Пусть не выступают с тобой в поход израильские воины! Господь не будет помогать израильтянам – сынам Ефрема.","8":"Если хочешь – иди, сражайся отважно! Но Бог повергнет тебя перед врагами, ведь погубить или спасти – во власти Бога».","9":"Амасия ответил человеку Божьему: «А как же быть с той сотней талантов, что я заплатил израильскому войску?» На это Божий человек сказал: «Господь может дать тебе гораздо больше!»","10":"Тогда Амасия распустил воинов, пришедших к нему из племени Ефрема, и они в страшном гневе на Иудею разошлись по домам.","11":"А Амасия в воодушевлении повел свое войско к Соляной Долине, и там они перебили десять тысяч сеирцев,","12":"а еще десять тысяч человек взяли живьем, и отведя их на вершину скалы, сбросили оттуда, и все они разбились.","13":"Тем временем наемники, которых Амасия отослал обратно и не взял с собой на войну, стали нападать на иудейские города от Самарии до Бет – Хорона. Там они перебили три тысячи человек и награбили много добра.","14":"Вернувшись после разгрома эдомитян, Амасия принес с собой сеирских божков. Он сделал их своими богами и стал им поклоняться и воскурять.","15":"Господь разгневался на Амасию и послал к нему пророка, который сказал ему: «Зачем ты поклоняешься богам чужих народов? Эти боги не смогли спасти свои народы, когда ты напал на них!»","16":"Он еще не кончил говорить, как царь ответил ему: «Что, тебя назначили царским советником? А ну, замолчи! Иначе будешь казнен!» Но прежде чем умолкнуть, пророк сказал: «Я знаю: Господь решил погубить тебя, раз ты творишь такие вещи и не желаешь выслушать мой совет».","17":"Амасия, царь Иудеи, принял решение отправить посланцев к Иоасу, сыну Иоахаза, сына Иегу, царю Израиля, и велел передать ему: «Выходи на бой! Сойдемся лицом к лицу!»","18":"Иоас, царь Израиля, велел ответить Амасии, царю Иудеи: «Как-то раз ливанский чертополох отправил посланцев к ливанскому кедру: „Выдавай, – говорит, – свою дочь замуж за моего сына\". Шел мимо зверь ливанский – и растоптал этот чертополох.","19":"Ты думаешь, что разгромил Эдом, – это вскружило тебе голову. Гордиться гордись – да только сидя дома. Зачем накликаешь на себя беду? И сам падешь, и вместе с тобой – Иудея».","20":"Но не послушал его Амасия – ведь Бог решил отдать его людей в руки врагов за то, что они почитали эдомских божков.","21":"Иоас, царь Израиля, выступил в поход – и сошлись они с Амасией лицом к лицу в Бет – Шемеше, что в Иудее.","22":"Иудеи были разбиты израильтянами и разбежались по домам.","23":"А сам Амасия, царь Иудеи, сын Иоаса, сына Ахазии, попал при Бет – Шемеше в плен к Иоасу, царю Израиля. Иоас привел Амасию к Иерусалиму, и там, сделав в стене пролом длиною в четыреста локтей, от Ефремовых ворот до Угловых, вошел в город.","24":"Он забрал все золото и серебро, всю утварь, какая нашлась в Божьем Храме (за нее отвечал Овед – Эдом), и сокровища, хранившиеся в царском дворце, взял заложников и вернулся в Самарию.","25":"Амасия, сын Иоаса, царь Иудеи, пережил Иоаса, сына Иоахаза, царя израильского, на пятнадцать лет.","26":"Прочее об Амасии от начала до конца описано в Книге царей Иудеи и Израиля.","27":"С того времени как Амасия отвернулся от Господа, против него в Иерусалиме начали составлять заговор. Амасия бежал в Лахиш, но заговорщики послали за ним в Лахиш своих людей и убили его.","28":"Тело увезли из Лахиша на лошадях, и Амасия был похоронен вместе с предками в Городе Иуды."},"26":{"1":"А царем, вместо Амасии, весь народ Иудеи сделал его сына, шестнадцатилетнего Озию.","2":"Это он вновь отстроил Элот и вернул его под власть Иудеи. Произошло это после того, как прежний царь упокоился рядом со своими предками.","3":"Когда Озия стал царем, ему было шестнадцать лет. Он царствовал в Иерусалиме пятьдесят два года. Его мать – Иехолия, родом из Иерусалима.","4":"Его деяния были угодны Господу, он во всем поступал так же, как его отец Амасия.","5":"Он почитал Бога, пока был жив Захария, искусный провидец Божий. И пока Озия почитал Господа, Бог помогал ему.","6":"Он вышел на войну с филистимлянами и разрушил стены Гата, Явне и Ашдода. Тогда же он построил города вокруг Ашдода и в области филистимлян.","7":"Бог помогал ему в войне с филистимлянами, арабами из Гур – Баала и меунеями.","8":"Аммонитяне платили Озие дань, и слава о нем дошла до самой египетской границы, ведь он был очень могущественен.","9":"Он построил укрепленные башни в Иерусалиме над Угловыми воротами, над воротами Долины и над углом стены.","10":"В пустыне он построил башни и вырубил в камне много колодцев для своих многочисленных стад. В предгорьях и на равнине были у него земледельцы, в горах и в садах – виноградари. Озия любил земледелие.","11":"У Озии было войско, состоящее из годных к военной службе, способных носить оружие мужчин, разделенных на отряды. Их список с указанием числа был составлен писцом Иеиэлом и распорядителем Маасеей под начальством Ханании, одного из царских сановников.","12":"Общее число глав родов, богатырей, было две тысячи шестьсот.","13":"Под их началом было войско: триста семь тысяч пятьсот воинов, готовых к бою, способных выступить против врагов царя.","14":"Для всего войска Озия приготовил щиты, копья, шлемы, доспехи, луки и камни для пращей.","15":"В Иерусалиме на башнях и на углах стен он установил хитроумные машины, чтобы метать стрелы и большие камни. Далеко разнеслась его слава, ибо он получал чудесную помощь, и так он стал очень могущественным.","16":"Но его могущество вскружило ему голову и привело к гибели: и он совершил преступление против Господа, Бога его. Он вошел в Господень Храм, чтобы воскурить благовония на жертвеннике для воскурений.","17":"Следом за ним вошел священник Азария, а с ним восемьдесят священников Господних, людей знатных.","18":"Они встали на пути царя Озии и сказали ему: «Не тебе, Озия, совершать воскурения Господу! Воскурения – дело священников, потомков Аарона, которые на то и посвящены. Выйди из святилища, ибо ты совершил преступление, и не принесет это тебе славы от Господа Бога».","19":"Озия, который уже взял в руки ковш для воскурений, разозлился. Но как только он разозлился на священников, на лбу у него проступила проказа – перед священниками, в Господнем Храме, рядом с жертвенником для воскурений!","20":"Первосвященник Азария и все священники взглянули на него – и увидели на лбу проказу. Они поспешно вывели его, да он и сам торопился выйти, ведь его поразил Господь.","21":"Царь Озия до самой смерти был болен проказой и жил в Бет – ха – Хофшит, ведь он был отлучен от Храма Господа. А царевич Иофам оставался в царском дворце и правил народом страны.","22":"Прочее об Озии от начала до конца записал пророк Исайя, сын Амоца.","23":"И упокоился Озия рядом со своими предками – похоронили его вместе с предками на царском кладбище. О нем говорили: прокаженный! Царем после него стал его сын Иофам."},"27":{"1":"Когда Иофам стал царем, ему было двадцать пять лет. Он царствовал в Иерусалиме шестнадцать лет. Его мать – Иеруша, дочь Цадока.","2":"Его деяния были угодны Господу, он во всем поступал так же, как его отец Озия, но, в отличие от отца, он не входил в Господень Храм. А народ по – прежнему был порочен.","3":"Иофам построил Верхние ворота Господнего Храма и возвел много построек при городской стене на холме Офел.","4":"Также он построил в горах Иудеи города, а в лесах – крепости и башни.","5":"Он воевал с царем аммонитян и подчинил его. Аммонитяне в тот год принесли ему дань: сто талантов серебра, десять тысяч коров пшеницы и десять тысяч коров ячменя. Такую же дань аммонитяне принесли ему на второй и на третий год.","6":"Иофам был силен, потому что прямым был его путь перед Господом, его Богом.","7":"Прочее об Иофаме, о всех его войнах и деяниях, написано в Книге царей Израиля и Иудеи.","8":"Когда Иофам стал царем, ему было двадцать пять лет. Он царствовал в Иерусалиме шестнадцать лет.","9":"И упокоился Иофам – был похоронен рядом с предками в Городе Давидовом. Царем после него стал его сын Ахаз."},"28":{"1":"Когда Ахаз стал царем, ему было двадцать лет. Он царствовал в Иерусалиме шестнадцать лет. Не творил он дел, угодных Господу, не брал пример со своего предка Давида,","2":"а шел по пути царей Израиля и даже делал литые статуи Ваалов.","3":"Он приносил жертвы в долине Бен – Хинном и сжигал собственных сыновей – подобные мерзости делали народы, которых Господь истребил, чтобы отдать их землю Израилю.","4":"И в капищах, и на холмах, и под каждым деревом ветвистым он закалывал и сжигал жертвы.","5":"Сначала Господь, его Бог, отдал Ахаза в руки арамейского царя: арамеи разбили его и увели много пленников в Дамаск. Потом Господь отдал Ахаза в руки израильского царя: тот устроил страшное побоище.","6":"Пеках, сын Ремалии, за один день перебил из иудеев сто двадцать тысяч человек, могучих воинов. Они оставили Господа, Бога своих отцов!","7":"3ихри, богатырь из ефремлян, убил царского сына Маасею, дворцового управителя Азрикама и Элкану, второго человека в государстве после царя.","8":"Израильтяне взяли в плен у своих родичей двести тысяч женщин и детей, награбили много добра. Добычу они отвезли в Самарию.","9":"А там был пророк Божий по имени Одед. Он вышел на встречу войску, возвращающемуся в Самарию, с такими словами: «Гнев Господа, Бога ваших отцов, обрушился на иудеев, поэтому Господь отдал их в ваши руки! Но вы убивали их с такой яростью, что она достигла небес!","10":"А теперь вы собираетесь жителей Иудеи и Иерусалима сделать своими рабами и рабынями? Разве на вас самих нет грехов перед Господом, вашим Богом?","11":"Слушайте, что я вам скажу! Отпустите из плена своих собратьев, ибо вы навлекаете на себя гнев Господень!»","12":"Несколько предводителей ефремлян – Азария, сын Иехоханана; Берехия, сын Мешиллемота; Езекия, сын Шаллума, и Амаса, сын Хадлая – тоже стали обвинять тех, кто вернулся с войны:","13":"«Вам не нужно было приводить сюда этих пленных, – сказали они, – чтобы на нас не легла вина перед Господом. Вы хотите увеличить число наших грехов и провинностей! Но вина наша и так велика, Господь и так в гневе на Израиль!»","14":"Вернувшиеся из похода передали пленников и награбленное добро вельможам и всей общине.","15":"Были поименно назначены люди, которые позаботились о пленных. Из военной добычи выделили одежду для тех, кто был раздет. Они одели их, обули, накормили, напоили, смазали раны, ослабших посадили на ослов и отвели пленных в Иерихон, Город Пальм, откуда было недалеко до их родичей, а сами вернулись в Самарию.","16":"В это время царь Ахаз послал к ассирийским царям за помощью.","17":"Эдомитяне вновь напали на иудеев, разгромили их и увели пленников,","18":"в то время как филистимляне продолжали разорять иудейские города в предгорьях и в пустыне Негев. Они захватили Бет – Шемеш, Айялон, Гедерот, Сохо вместе с селениями вокруг него, Тимну и Гимзо вместе с селениями вокруг них – и сами поселились в этих городах.","19":"Господь так унизил Иудею из-за Ахаза, царя Израилева, который развратил Иудею, сделал ее неверной Господу.","20":"Ассирийский царь Тиглатпаласар напал на него и осадил, вместо того, чтобы помочь ему.","21":"Ахаз взял сокровища из Храма Господа, царского дворца и у сановников и послал ассирийскому царю, но и это не помогло.","22":"В это трудное время царь Ахаз все больше и больше нарушал верность Господу.","23":"Он приносил жертвы богам Дамаска, которые нанесли ему поражение, и рассуждал так: «Боги арамейских царей пришли своим людям на помощь! Я буду приносить им жертвы, и они станут помогать мне». Но эти боги принесли гибель Ахазу и всему Израилю.","24":"Ахаз собрал и унес из Божьего Храма всю утварь, затворил двери Господнего Храма и стал воздвигать жертвенники на каждом углу в Иерусалиме;","25":"в каждом городе по всей Иудее он сооружал капища и там он приносил жертвы чужим богам. Так он оскорблял Господа, Бога своих отцов.","26":"Прочее о деяниях и поступках Ахаза, и что было в начале, и что было в конце, написано в «Книге царей Иудеи и Израиля».","27":"И упокоился Ахаз рядом со своими предками – его похоронили в самом городе, в Иерусалиме, но не там, где похоронены цари. Царем после него стал его сын Езекия."},"29":{"1":"Езекия воцарился, когда ему было двадцать пять лет. Он царствовал в Иерусалиме двадцать девять лет. Его мать – Ави, дочь Захарии.","2":"Он творил дела, угодные Господу, так же, как предок его Давид.","3":"В первый месяц первого года своего царствования он открыл и починил врата Господнего Храма.","4":"Он привел туда священников и левитов, собрал их на восточной площадке","5":"и сказал им: «Слушайте меня, левиты! Освятите и очистите себя, освятите Храм Господа, Бога ваших отцов, уберите из святилища всякую скверну.","6":"Отцы наши грешили и творили дела, ненавистные Господу, нашему Богу. Они оставили Его, отвернулись от жилища Его и встали к Нему спиной.","7":"Они даже затворили двери притвора Храма и погасили светильники. Они не совершали в святилище воскурений и всесожжении Богу Израиля.","8":"За это прогневался Господь на Иудею и Иерусалим, заставил их трястись от ужаса, обрек их на опустошение и унижение, как вы и сами видите.","9":"За это наши отцы были убиты, наши дети и жены уведены в плен.","10":"Но теперь я решил заключить договор с Господом, Богом Израиля, чтобы отвратить от нас Его пылающий гнев.","11":"Хватит вам бездействовать, дети мои! Вас избрал Господь, чтобы вы предстояли пред Господом и служили Ему, чтобы вы совершали свое служение и воскурения».","12":"Тогда принялись за дело левиты: Махат, сын Амасая, и Иоиль, сын Азарии (они были кехатитами); из мераритов – Киш, сын Авди, и Азария, сын Иехаллелела; из потомков Гершона – Иоах, сын Зиммы, и Эден, сын Иоаха;","13":"из потомков Элицафана – Шимри и Иеиэл; из потомков Асафа – Захария и Маттания;","14":"из потомков Хемана – Иехиэл и Шими ; из потомков Иедутуна – Шемая и Уззиэл.","15":"Они собрали своих собратьев, освятили и очистили себя и отправились совершать очищение Господнего Храма, как приказал царь, следуя слову Господа.","16":"Священники вошли во внутреннюю часть Храма Господа, чтобы его очистить. Они стали выносить всякую мерзость, какая была в Храме Господа, во двор. Там они передавали ее левитам, которые уносили все это к потоку Кедрон.","17":"Они начали освящение в первый день первого месяца, и в восьмой день они достигли Господнего притвора. Освящение Храма продолжалось еще восемь дней и было завершено в шестнадцатый день первого месяца.","18":"Тогда они отправились к царю Езекии со словами: «Мы очистили весь Господень Храм, жертвенник для всесожжении со всеми его принадлежностями и стол для хлеба со всеми его принадлежностями.","19":"Мы также приготовили и освятили всю утварь, которую осквернил царь Ахаз, совершая преступления во время своего правления. Теперь она у Господнего жертвенника».","20":"Следующим утром царь Езекия собрал городских сановников и отправился в Храм Господень.","21":"Они привели с собой семь быков, семь баранов, семь ягнят и семь козлов для очистительной жертвы за царство, за святилище и за всю Иудею. Царь приказал священникам, потомкам Аарона, сжечь животных на Господнем жертвеннике.","22":"Священники закололи быков, собрали их кровь и окропили ею жертвенник, потом закололи баранов и окропили их кровью жертвенник, потом закололи ягнят и окропили их кровью жертвенник.","23":"Козлов, приготовленных для очистительной жертвы, подвели к царю и всему собранию, чтобы они возложили на них руки.","24":"Священники закололи козлов и окропили их кровью жертвенник, очищая его во искупление всего Израиля, ибо ради всего Израиля царь повелел принести всесожжение и жертву за грех.","25":"Левитам он приказал стоять в это время в Господнем Храме с кимвалами, лирами и арфами, как было установлено Давидом, царским провидцем Гадом и пророком Нафаном – это Господь так повелел через Своих пророков.","26":"Левиты стояли с музыкальными инструментами Давида, а священники с трубами.","27":"Езекия повелел возложить всесожжение на жертвенник, и когда началось жертвоприношение, то началась и песнь Господня под звуки труб и инструментов Давида, царя Израиля.","28":"И все собравшиеся пали ниц под звуки песни и труб, и оставались так, пока не завершилось всесожжение.","29":"Когда всесожжение было окончено, царь и все его приближенные преклонили колени и пали ниц.","30":"Царь Езекия и сановники приказали левитам восхвалять Господа словами Давида и провидца Асафа. Они с радостью воспели хвалу, и поклонились и пали ниц.","31":"Тогда Езекия сказал: «Теперь вы все посвятили себя Господу. Приходите сюда, приносите жертвы и благодарственные приношения в Храм Господень!» Тогда все собравшиеся стали приносить жертвы и благодарственные приношения, и каждый, кто хотел, приносил всесожжение.","32":"Вот общее число всесожжении, принесенных собранием: семьдесят быков, сто баранов, двести ягнят. Все это было принесено как всесожжение Господу.","33":"Общее число священных приношений: шестьсот быков и три тысячи баранов.","34":"Но священников было слишком мало, они не успевали снимать шкуры с жертвенных животных. Их собратья левиты помогали им, пока не закончилось служение и пока другие священники не совершили обряд освящения. (Левиты отнеслись к обряду освящения более добросовестно, чем священники.)","35":"Господу было принесено много всесожжении, много жира пиршественных жертв и много возлияний. Так было восстановлено служение в Господнем Храме.","36":"Езекия и весь народ ликовали, что Бог укрепил Свой народ – настолько все это произошло неожиданно."},"30":{"1":"Затем Езекия созвал всех израильтян и иудеев совершить в Господнем Храме Пасху Господа, Бога Израиля. Он даже написал племенам Ефрема и Манассии, приглашая их придти в Иерусалим.","2":"Царь, посоветовавшись со своими сановниками и всей иерусалимской общиной, решил совершить Пасху во второй месяц –","3":"они не могли совершать ее в обычное время, потому что необходимое количество священников еще не прошло освящения и народ еще не собрался в Иерусалиме.","4":"И царю, и всей общине показалось правильным поступить именно так.","5":"Они решили объявить об этом по всему Израилю, от Беэр – Шевы и до Дана, приглашая всех совершить в Иерусалиме Пасху Господа, Бога Израиля – не часто ее совершали так, как написано в Законе.","6":"Гонцы по царскому указу возвестили по всему Израилю и по всей Иудее послание царя и его сановников, в котором говорилось: «Сыны Израилевы! Обратитесь к Господу, Богу Авраама, Исаака и Израиля, и тогда Он обратится к вам – к тем, кто уцелел после нападения ассирийских царей.","7":"Не будьте подобны вашим отцам и родичам, которые нарушили верность Господу, Богу их отцов, за что Он и навел на них разорение, как вы сами видите.","8":"Так не упрямьтесь, подобно вашим отцам! Возденьте руки к Господу и приходите в святилище, которое освящено навек, и послужите Господу, вашему Богу, и тогда Он отвратит от вас Свой пылающий гнев.","9":"И если вы обратитесь к Господу, то к вашим родичам и вашим детям станут милосердны пленившие их ассирийцы и дадут им вернуться в эту страну, ибо Господь, ваш Бог, добрый и милосердный – Он не отвернется от вас, если вы обратитесь к Нему».","10":"Гонцы шли от одного города к другому, обходя земли Ефрема, Манассии и даже Завулона, но их встречали только насмешками и издевательствами.","11":"Но некоторые люди из племен Асира, Манассии и Завулона все же смирились и пришли в Иерусалим.","12":"В Иудее же Господь вселил в сердца людей единодушное стремление исполнить повеление царя и его сановников во исполнение слова Господня.","13":"В Иерусалиме собралось во второй месяц множество людей, чтобы отпраздновать праздник Пресного Хлеба – огромное собрание!","14":"Тогда они уничтожили все жертвенники в Иерусалиме, в том числе и жертвенники для воскурений, и бросили все это в Кедронский овраг.","15":"Пасхальных ягнят закололи в четырнадцатый день второго месяца. Священники и левиты устыдились, освятили и очистили себя и принесли всесожжения в Господнем Храме.","16":"Они стали исполнять свои служения, как полагается по закону Моисея, человека Божьего. Священники брали из рук левитов жертвенную кровь и совершали окропление.","17":"Поскольку среди собравшегося народа было много людей, которые не прошли освящения, левитам было поручено заколоть ягнят за всех, кто был нечист для того, чтобы совершать священные приношения Господу.","18":"Множество пришедших из племен Ефрема, Манассии, Иссахара и Завулона не прошли очищения, но все же они ели пасхальных ягнят, вопреки написанному в Законе, ибо Езекия помолился о них так: «Благой Господь да простит каждого,","19":"кто всем сердцем стремится к Богу – к Господу, Богу своих отцов, но не прошел очищения, предписанного для святилища».","20":"Господь услышал молитву Езекии и исцелял народ.","21":"Израильтяне, собравшиеся в Иерусалиме, с великой радостью праздновали праздник Пресного Хлеба в течение семи дней, левиты каждый день восхваляли Господа, а священники воздавали Господу славу игрой на музыкальных инструментах.","22":"Езекия воодушевил каждого левита, и они показали, что хорошо знают Господне служение. Семь дней они ели жертвенное мясо, приносили пиршественные жертвы и благодарили Господа, Бога своих отцов.","23":"Вся община решила продлить праздник еще на семь дней, и эти семь дней они праздновали с радостью;","24":"Езекия, царь Иудеи, дал общине тысячу быков и семь тысяч баранов, а сановники дали тысячу быков и десять тысяч баранов. Многие священники освятили и очистили себя.","25":"Радость охватила всех собравшихся там иудеев, и священников, и левитов, и тех, кто пришел на праздник из Израиля, и всех переселенцев, пришедших из Израильской земли и живших в Иудее.","26":"В Иерусалиме поднялось ликование, ибо не бывало такого в Иерусалиме со дней Соломона, сына Давидова, царя Израиля.","27":"Священники и левиты стали благословлять народ, и их голос был услышан, ибо их молитва дошла до небес – святой обители Бога."},"31":{"1":"Когда празднование закончилось, все сыны Израилевы, которые там были, отправились по иудейским городам. Они разбили священные камни, срубили дерева Ашеры, разрушили капища и жертвенники – все до последнего в землях Иуды, Вениамина, Ефрема, Манассии. После этого все сыны Израилевы вернулись каждый к своему наделу, в свое селение.","2":"Езекия восстановил подразделения священников и левитов в соответствии с их служениями. Обязанностями священников и левитов было: совершать всесожжения и пиршественные жертвы, прислуживать, исполнять благодарственные и хвалебные песнопения у ворот Стана Господня.","3":"Царь выделял из своего имущества долю на совершение всесожжении: утренних и вечерних, совершаемых по субботам, в новолуния и по праздникам, предписанным Законом Господа.","4":"Народу, жителям Иерусалима, он повелел заботиться о содержании священников и левитов, чтобы они могли посвятить себя Закону Господа.","5":"И как только было об этом объявлено, сыны Израилевы стали приносить в изобилии первые плоды своего урожая – зерно, вино, оливковое масло, мед и все, что росло на их полях, – и отдавать десятину.","6":"Израильтяне и иудеи, жившие в иудейских городах, тоже принесли десятину от крупного и мелкого скота и от святыни, от того, что было посвящено Господу Богу. Скопилось огромное множество запасов.","7":"Приношения начали собирать в третий месяц и закончили в седьмой.","8":"Когда пришли Езекия и сановники и увидели эти запасы, они благословили Господа и народ Его, Израиль,","9":"Езекия стал расспрашивать священников и левитов об этих запасах,","10":"и ему ответил Азария, первосвященник из потомков Цадока: «С тех пор как люди стали приносить пожертвования в Храм Господень, всем хватит, чтобы есть досыта, и еще останется. Потому что Господь благословил Свой народ, и у нас всего остается в избытке».","11":"Езекия велел приготовить кладовые в Господнем Храме, и это было исполнено.","12":"Все приношения, десятина и то, что было посвящено, было без обмана сложено туда. Главным распорядителем был левит Канания, а вторым после него – его брат Шими.","13":"Иехиэл, Азазия, Нахат, Асаил, Иеримот, Иозавад, Элиэл, Исмахия, Махат и Беная были смотрителями под руководством Канании и брата его Шими, которых назначил царь Езекия. Главным в Божьем Храме был Азария.","14":"Левит Коре, сын Имны, привратник Восточных врат, был ответственным за добровольные жертвы Богу: он распределял пожертвования Господу и святыню святынь.","15":"Ему были подчинены Эден, Миньямин, Иисус, Шемая, Амария и Шехания, которые без обмана распределяли все это в священнических городах среди своих собратьев, в соответствии с их подразделениями, от старших и до младших.","16":"Кроме того, они наделяли всех, начиная с трехлетнего возраста, кто был занесен в родословные списки и должен был однажды взойти в Господень Храм на свое ежедневное служение, в соответствии со своими обязанностями и своей сменой.","17":"Священники были расписаны по своим отеческим родам, а также и левиты – начиная с двадцати лет и старше, в соответствии с их сменами и разрядами.","18":"Записаны были даже малые дети; и жены, и сыновья, и дочери всех, кто входил в сообщество, кто был верен своему посвящению.","19":"А что до потомков Аарона, священников, которые жили на пастбищах рядом со своими городами, то были поименно назначены люди, которые наделяли всех людей мужского пола из священнических родов и всех, кто был записан в родословиях левитов.","20":"Вот преобразования, которые совершил Езекия по всей Иудее. Дела его были угодны Господу, он поступал честно и правильно.","21":"Во всех своих начинаниях – в служении Божьему Храму, Закону и заповедям – он стремился к Богу и он действовал от чистого сердца, и потому преуспевал."},"32":{"1":"После всех этих событий, в которых Езекия явил свою верность Господу, в Иудею вторгся ассирийский царь Синаххериб. Он начал осаду укрепленных городов, намереваясь их захватить.","2":"Когда Езекия узнал о том, что Синаххериб напал на Иудею и собирается идти войной на Иерусалим,","3":"он, посовещавшись со своими военачальниками и воинами и получив от них одобрение, решил перекрыть воду в источниках, располагавшихся за городской стеной.","4":"Собралось много людей, и они перекрыли источники и поток, который растекался по стране, говоря: «Сюда придут ассирийские цари – так к чему оставлять им в изобилии воду?»","5":"Приободрившись, Езекия отстроил разрушенные участки городской стены, на ней возвел башни, снаружи построил еще одну стену, а также укрепил Милло в Городе Давидовом. Он приготовил много оружия и щитов.","6":"Он назначил военачальников, собрал их на площади у городских ворот и стал увещевать такими словами:","7":"«Будьте твердыми и стойкими! Не бойтесь и не страшитесь царя ассирийского со всем его воинством, ибо с нами еще большая сила!","8":"У него – человеческая мощь, но нам поможет и будет за нас сражаться Господь, наш Бог». И люди обрели уверенность, выслушав, что сказал им Езекия, царь иудейский.","9":"После этого ассирийский царь Синаххериб послал к Иерусалиму своих приближенных (сам он во главе своего войска в это время осаждал Лахиш) с речью к иудейскому царю Езекии и ко всем иудеям, находившимся в Иерусалиме. Он велел передать им:","10":"«Так говорит ассирийский царь Синаххериб! На что вы надеетесь, как вы собираетесь переждать осаду Иерусалима?","11":"Разве не лжет вам Езекия, разве не собирается уморить вас голодом и жаждой, когда говорит: „Господь, наш Бог, спасет нас от ассирийского царя\"?","12":"Но не Его ли капища и жертвенники уничтожил Езекия, велев жителям Иудеи и Иерусалима поклоняться и совершать воскурения лишь здесь, в Иерусалиме, перед этим жертвенником?","13":"Но разве вы сами не знаете, что сделали мои предки и я сам с народами всех стран? Что, смогли помочь этим народам их боги, смогли они спасти от меня их земли?","14":"Кто из богов всех тех народов, что были уничтожены моими предками, смог спасти от меня свой народ? Как же вас спасет ваш Бог?","15":"Так что пусть не обольщает вас Езекия, пусть не тешит этой пустой надеждой. Не верьте ему, ибо нет ни у одного народа и ни в одном царстве такого бога, который смог бы спасти свой народ от меня или от моих предков. И ваш Бог не избавит вас от меня!»","16":"И другое говорили приближенные Синаххериба против Господа Бога и Его раба Езекии.","17":"Еще Синаххериб написал письма, в которых бранил Господа, Бога Израиля, такими словами: «Как боги народов всех стран не спасли их от меня, так и Бог Езекии не спасет Свой народ от меня».","18":"Все это они кричали громким голосом по – еврейски, чтобы слышал весь собравшийся на стене иерусалимский народ. Они надеялись запугать и устрашить народ, чтобы легче было завоевать город.","19":"Они говорили о Боге Иерусалима точно так же, как и о богах других народов, тех богах, что сделаны руками человеческими.","20":"Царь Езекия и пророк Исайя, сын Амоца, стали молиться об этом, взывать о помощи к небу.","21":"И Господь послал ангела, который уничтожил всех могучих воинов, и военачальников, и полководцев в войске ассирийского царя. Тот с позором отправился обратно в свою страну. А когда он вошел в храм своего бога, его родные сыновья закололи его мечом.","22":"Так Господь спас Езекию и жителей Иерусалима от ассирийского царя Синаххериба. Он оберегал их и от всех остальных врагов, ограждал их со всех сторон.","23":"После этих событий многие стали приносить в Иерусалим пожертвования Господу и подношения иудейскому царю Езекии, прославившемуся среди других народов.","24":"В это время Езекия заболел смертельной болезнью и взмолился к Господу. Тот ответил ему и послал знамение.","25":"Но Езекия не отозвался должным образом, потому что возгордился, и Гнев небесный обрушился на него, на Иудею и Иерусалим.","26":"Тогда Езекия смирил свою гордыню, как и жители Иерусалима, и до конца жизни Езекии гнев Господень более не карал них.","27":"Езекия был очень богат и славен. Он устроил сокровищницы для своего серебра и золота, для драгоценных камней, благовоний, щитов и иных ценностей.","28":"Также он делал склады для зерна, для вина и для оливкового масла, стойла для крупного и загоны для мелкого скота.","29":"Он устраивал поселения и владел множеством скота, потому что Господь даровал ему огромное имущество.","30":"Это Езекия перекрыл верхний выход источника Гихон и провел от него туннель к западной части Города Давидова. Езекии во всех его делах сопутствовал успех.","31":"А когда вавилонские правители отправили к нему своих посланников, чтобы разузнать о знамении, которое было в его стране, то Бог оставил его, чтобы испытать его, чтобы стало явным сокрытое в его сердце.","32":"Прочие деяния Езекии и доказательства его верности записаны в видении пророка Исайи, сына Амоца, в Книге иудейских и израильских царей.","33":"Когда Езекия почил с предками, его похоронили на возвышении подле сыновей Давида. После его смерти вся Иудея и все жители Иерусалима воздали ему почести. После него воцарился его сын Манассия."},"33":{"1":"Двенадцати лет от роду Манассия стал царем; пятьдесят пять лет царствовал он в Иерусалиме.","2":"Он творил дела, ненавистные Господу – он совершал такие же гнусности, как и те народы, чью землю Господь отдал израильтянам.","3":"Он восстановил капища, разрушенные его отцом Езекией; построил жертвенники Ваалу; воздвиг древо Ашеры. Он поклонялся всему небесному воинству и служил ему.","4":"Даже в Храме Господа, о котором Господь сказал: «Да будет имя Мое в Иерусалиме навеки», Манассия понастроил жертвенников.","5":"В обоих дворах Господнего Храма он устраивал жертвенники всему небесному воинству.","6":"Он принес в огненную жертву собственных сыновей в долине Бен – Хинном. Он ворожил, гадал и колдовал, обращался к вызывателям мертвых и духов – ведунов – творил много дел, ненавистных Господу, оскорблял Господа.","7":"Он велел изготовить статую и поставить в Божьем Храме, о котором Бог говорил Давиду и его сыну Соломону: «В этом Храме, в Иерусалиме – городе, который Я избрал Себе из всех владений племен Израилевых, Мое имя будет пребывать вовеки.","8":"Никогда больше Я не заставлю израильтян скитаться на чужбине, вдали от страны, которую Я отдал их отцам. Только пусть они соблюдают все, что Я им повелел – Закон, установления и правила, которые передал им Моисей!»","9":"Но Манассия сбил жителей Иудеи и Иерусалима с пути, и они стали поступать еще хуже, чем те народы, которые Господь истребил, чтобы дать место израильтянам.","10":"Господь говорил Манассии и Своему народу, но они Ему не вняли.","11":"Тогда Господь привел против него военачальников ассирийского царя, которые схватив его крюками и сковав медными цепями, уволокли в Вавилон.","12":"И когда пришла к нему беда, он стал умолять Господа, своего Бога, глубоко смирился перед Богом своих отцов.","13":"Он взмолился к Нему, и Бог снизошел к его жалобам, выслушал его мольбу, вернул его в Иерусалим на царский престол, и так Манассйя познал, что единственный Бог – Господь.","14":"После этого он отстроил внешнюю стену Города Давидова к западу от Тихона, что в долине, и до Рыбных ворот; стену он сделал очень высокой. Во все укрепленные города в Иудее он отправил военачальников.","15":"Он избавился от чужих богов, убрал изображения из Храма Господа, от жертвенников, воздвигнутых на Храмовой горе в Иерусалиме, и вынес все это прочь из города.","16":"Он восстановил жертвенник Господу и стал приносить Ему пиршественные и благодарственные жертвы, и велел иудеям служить Господу, Богу Израиля.","17":"Но народ по – прежнему приносил жертвы в капищах, хотя и приносил их только Господу, своему Богу.","18":"Прочее о деяниях Манассии, его молитва Богу и слова провидцев, говоривших с ним от имени Господа, Бога Израиля, записаны в Деяниях царей Израиля.","19":"И о его молитве, и об оказанном ему снисхождении, и о всех его грехах, неверности, о местах, в которых он устраивал капища и воздвигал дерева Ашеры и изваяния (еще до того, как раскаялся) – обо всем этом написано в Деяниях Хозая.","20":"Манассия отошел к предкам и его похоронили в его собственном дворце. Царем после него стал его сын Амон.","21":"Двадцати двух лет от роду Амон стал царем; два года царствовал он в Иерусалиме.","22":"Его дела были так же неугодны Господу, как и дела его отца, Манассии. Амон приносил жертвы и служил всем идолам, сделанным его отцом Манассией.","23":"Но, в отличие от своего отца Манассии, Амон не смирился перед Господом, а только увеличивал свою вину.","24":"Его приближенные составили против него заговор и убили его прямо во дворце.","25":"Но народ перебил всех заговорщиков и провозгласил царем Иосию, сына Амона."},"34":{"1":"Восьми лет от роду Иосия стал царем; тридцать один год царствовал он в Иерусалиме.","2":"Он творил дела, угодные Господу. Во всем следовал он отцу своему Давиду, шел по его пути, не уклоняясь ни вправо, ни влево.","3":"На восьмом году своего царствования, еще юношей, он устремился к Богу своего предка Давида, а на двенадцатый год он начал очищать Иудею и Иерусалим от капищ, дерев Ашеры, изваяний и литых статуй.","4":"Он велел разрушить жертвенники Ваалов и стоявшие на них курильницы, он срубил дерева Ашеры, изваяния и литые статуи – все это он разбил вдребезги и рассыпал по могилам тех, кто прежде приносил им жертвы,","5":"а кости жрецов он сжег на их жертвенниках – и так очистил Иудею и Иерусалим.","6":"Также в городах Манассии, Ефрема, Симеона и даже Неффалима, по всей земле Израиля, он повсеместно уничтожал их храмы,","7":"разрушал жертвенники и дерева Ашеры, вдребезги разбивал изваяния, сносил кумирни. Затем он вернулся в Иерусалим.","8":"В восемнадцатый год своего правления, очистив всю страну и Храм, Иосия поручил Шафану, сыну Аца - лии, и Маасее, городскому правителю, а также глашатаю Иоаху, сыну Иоахаза, отремонтировать Храм Господа Бога.","9":"Они пришли к Хилкии, верховному священнику, и отдали ему серебро, которое было принесено в Храм, – его собрали левиты, стражи ворот, среди племен Манассии и Ефрема – со всех уцелевших израильтян, со всех иудеев, вениамитян и со всех жителей Иерусалима.","10":"Его передали тем, кто был назначен вести работы в Храме Господа. Из этих денег они оплачивали труд рабочих, которые проводили ремонтные и восстановительные работы в Храме Господа:","11":"плотников, строителей – а также покупку тесаного камня и дерева для креплений и для того, чтобы отстроить здания, разрушенные царями Иудеи.","12":"Работники выполняли свою работу честно, а руководили ими левиты Яхат и Авдий из рода мераритов, а также Захария и Мешуллам из рода кехатитов. Все левиты, хорошо умевшие играть на музыкальных инструментах,","13":"сопровождали носильщиков и следили за всем, что делали рабочие. Некоторые из левитов были писцами, распорядителями и стражами ворот.","14":"Когда из Храма доставали хранящееся там серебро, священник Хилкия нашел книгу Закона Господнего, который был записан Моисеем.","15":"Тогда Хилкия сказал писцу Шафану: «Я нашел в Храме Господа книгу Закона!» И Хилкия передал свиток Шафану.","16":"Шафан отнес ее царю и рассказал ему обо всем: «Твои слуги исполняют все, что ты им поручил.","17":"Они переплавили серебро, поступившее в Храм Господа, и передали смотрителям и работникам».","18":"Потом добавил: «Священник Хилкия передал мне свиток». И Шафан прочел свиток царю.","19":"Выслушал царь слова Закона и разодрал свои одежды.","20":"Он повелел Хилкии, Ахикаму, сыну Шафана, Авдону, сыну Михея, писцу Шафану и Асае, царскому слуге:","21":"«Идите, вопросите Господа обо мне и о тех, кто остался в Израиле и Иудее: как быть с тем, что написано в этой найденной ныне книге? Ибо велика ярость Господня, которая изольется на нас за то, что наши отцы не соблюдали повелений Господа и не поступали так, как нам предписано в этой книге!»","22":"Хилкия и царские посланники пошли к пророчице Хулде, жене Шаллума, сына Токхата, сына Хасры, хранителя одежд. Жила она в Иерусалиме, в Новом Городе. Они все рассказали ей,","23":"и она ответила: «Так говорит Господь, Бог Израиля! Передайте тому, кто послал вас ко мне:","24":"„Так говорит Господь: скоро, скоро Я наведу на этот город и на его жителей страшную беду; исполнится все, что записано в этой книге, которую читали иудейскому царю!","25":"Эти люди оставили Меня, они приносили жертвы другим богам, они всеми своими поступками оскорбляли Меня! За это изольется Моя ярость против этого города – и не угаснет!\"","26":"А царю Иудеи, который послал вас вопросить Господа, передайте: „Так говорит Господь, Бог Израиля: ты слышал, что написано в этой книге.","27":"Услышав, что Я обещал сделать с этим городом и с его жителями, ты смирился и склонился перед Господом, и разодрал одежды и плакал передо Мной. За это и Я услышал тебя, – говорит Господь.","28":"Я дам тебе спокойно отойти к отцам, ты будешь с миром погребен в своей гробнице, и глаза твои не увидят той страшной беды, которую Я наведу на этот город и его жителей\"». Когда ответ пророчицы передали царю,","29":"он повелел собрать всех старейшин Иудеи и Иерусалима.","30":"Он вошел в Храм Господа, а следом за ним все жители Иудеи и Иерусалима, священники, пророки и весь народ, стар и млад. И царь прочел им от начала до конца всю Книгу договора, что была найдена в Храме Господа.","31":"Царь встал на свое место и подтверждал перед Господом договор – быть верным Господу, от всего сердца и от всей души исполнять Его повеления, предписания и законы, соблюдать все условия договора, записанные в свитке.","32":"Он велел, чтобы это подтвердили все, кто жил в Иерусалиме и на земле Вениамина. И жители Иерусалима стали поступать так, как велел Божий договор – договор Бога их отцов.","33":"Иосия убрал из подвластных израильтянам земель все мерзости и заставил всех жителей Иерусалима служить Господу, Богу их, и они исполняли это, пока Иосия был жив."},"35":{"1":"Иосия совершил в Иерусалиме Пасху Господу. Пасхального ягненка заклали в четырнадцатый день первого месяца.","2":"Иосия определил обязанности священников и вдохновил их на служение в Господнем Храме.","3":"А левитам, святым Господним, наставлявшим всех израильтян, он сказал: «Оставьте святой ковчег в Храме, который построил Соломон, сын Давида, царь Израиля! Это не ваша забота. Служите Господу, вашему Богу, и Его народу, Израилю!","4":"Приготовьтесь: разделитесь по отеческим родам, как предписал царь Израиля Давид и его сын Соломон.","5":"В святилище пусть каждый отряд левитов встанет рядом со своими родичами из народа.","6":"Заколите пасхального ягненка, освятите и очистите себя и приготовьте его для своих родичей, совершая все, как повелел Господь через Моисея».","7":"Иосия дал народу тридцать тысяч ягнят и козлят и три тысячи быков из своих стад – пасхальные жертвы для всех собравшихся.","8":"Его сановники дали народу, священникам и левитам скот для добровольных приношений. Хилкия, Захария и Иехиэл, распорядители в Господнем Храме, дали священникам две тысячи шестьсот ягнят и козлят и триста быков для пасхальных жертв.","9":"Канания вместе со своими собратьями Шемаей и Нетанэлом, Хашавия, Иеиэл и Иозавад – начальники левитов – предоставили пять тысяч ягнят и козлят и пятьсот быков для пасхальных жертвоприношений.","10":"Богослужение было подготовлено. Священники заняли свои места, левиты встали по отрядам, как приказал царь.","11":"Левиты зарезали пасхальных ягнят и сняли с них шкуры, а священники совершили окропление кровью.","12":"Левиты отделили и отдали народу части животных, предназначенных для жертвоприношения, чтобы простой народ, разделившись по родам, мог принести жертву Господу, как записано в книге Моисея. Подобным образом поступали и с быками.","13":"Пасхальных ягнят они готовили на огне, как положено, а священные части жертв готовили в горшках, котлах и тазах и с поспешностью раздавали мясо народу.","14":"После этого левиты приготовили жертвенное мясо для себя и для священников, потому что священники, потомки Аарона, до самой ночи совершали всесожжения и сжигали жир жертв. Левиты приготовили все для себя и для священников, потомков Аарона.","15":"Певцы, потомки Асафа, находились на своих местах, как им повелели Давид, Асаф, Хеман и царский провидец Иедутун. У каждых ворот стояли привратники: им не было нужды оставлять свою службу, так как их собратья – левиты все приготовили и для них.","16":"В тот день все служили Господу: они совершили Пасху и принесли всесожжения на Господнем жертвеннике, как и приказал царь Иосия.","17":"Все собравшиеся израильтяне праздновали Пасху и праздник Пресного хлеба в течение семи дней.","18":"Такой Пасхи не бывало в Израиле со времен пророка Самуила. Ни один израильский царь не праздновал Пасху так, как Иосия вместе со священниками, левитами и всеми иудеями и израильтянами, находившимися тогда в Иерусалиме.","19":"Эта Пасха была совершена на восемнадцатый год царствования Иосии.","20":"После всех этих событий, когда Иосия восстановил храмовое богослужение, египетский царь Нехо, выступил в поход на Каркемиш, что на Евфрате, а Иосия выступил со своим войском ему навстречу.","21":"Тогда тот отправил к нему гонцов, чтобы передать: «Разве воюем мы с тобой, царь иудейский? Не против тебя я выступил в поход, а против царства, которое ведет со мной войну. Бог велел мне торопиться, Он на моей стороне. Остановись, а не то Бог тебя погубит!»","22":"Но Иосия, который уже вооружился на битву, не отступил. Он не послушался того, что по велению Бога говорил ему Нехо. В долине Мегиддо вступил в бой.","23":"Лучники попали в царя Иосию, и тогда царь сказал своим слугам: «Вынесите меня отсюда, я тяжело ранен».","24":"Слуги вытащили его из колесницы, переложили в другую и отвезли в Иерусалим. Там он умер. Его похоронили в гробнице его предков. Вся Иудея и Иерусалим оплакивали Иосию.","25":"Иеремия составил плач об Иосии, и вплоть до сего дня все певцы и певицы оплакивают его. В Израиле это вошло в обычай, и песня эта записана среди Плачей.","26":"Прочее об Иосии, о том, как праведно он жил, следуя Закону Господа,","27":"и о его деяниях написано от начала до конца в Книге царей Иудеи и Израиля."},"36":{"1":"Тогда народ сделал царем в Иерусалиме вместо Иосии его сына Иоахаза.","2":"Двадцати трех лет от роду Иоахаз стал царем; три месяца царствовал он в Иерусалиме.","3":"Египетский царь лишил его престола в Иерусалиме, а на иудейскую страну наложил дань – сто талантов серебра и талант золота.","4":"На престол Иудеи и Иерусалима царь Египта возвел Элиакима, брата Иоахаза, и дал ему новое имя Иоаким. А Иоахаза фараон Нехо увел в Египет.","5":"Двадцать пять лет было Иоакиму, когда он стал царем; одиннадцать лет он царствовал в Иерусалиме. Его дела были ненавистны Господу.","6":"Навуходоносор, царь Вавилона, пошел на него войной. Он заковал Иоакима в кандалы и увел в Вавилон.","7":"Еще Навуходоносор унес в Вавилон часть утвари Храма Господа и поместил ее в своем вавилонском дворце. «Прочее о деяниях Иоакима, о том, какие мерзости он творил, и о том, что с ним произошло, написано в Книге царей Израиля и Иудеи. Царем после него стал Иехония, его сын.","9":"Восьми лет от роду Иехония стал царем; три месяца и десять дней царствовал он в Иерусалиме. Его дела были ненавистны Господу.","10":"В начале следующего года Навуходоносор послал за ним. Его угнали в Вавилон и унесли драгоценности из Храма Господа. Царем над Иудеей и Иерусалимом Навуходоносор поставил родственника Иехонии по имени Седекия.","11":"Двадцать один год было Седекии, когда он стал царем; одиннадцать лет царствовал он в Иерусалиме.","12":"Его дела были ненавистны Господу. Он не смирился даже перед пророком Иеремией, через которого говорил Господь.","13":"Он восстал против царя Навуходоносора, который взял с него клятву перед Богом. Он упорствовал и упрямился, не желая обратиться к Господу, Богу Израиля.","14":"Точно так же все верховные священники и народ грешили все больше и больше, подражая мерзостям прочих народов и оскверняя Храм, который Господь освятил в Иерусалиме.","15":"Господь, Бог их отцов, снова и снова обращался к ним через Своих посланников, жалея Свой народ и Свою обитель.","16":"Но они высмеивали Божьих посланников, презирали Его слова и издевались над Его пророками, пока Божий гнев не обрушился на Его народ, и тогда не было уже спасения.","17":"На них пошел войной вавилонский царь и перебил их юношей в святом Храме. Он не жалел ни юноши, ни девы, ни седовласого старика – все было отдано в его руки.","18":"В Вавилон была увезена вся утварь Божьего Храма, большая и маленькая, все сокровища Храма Господа и все сокровища царя и вельмож.","19":"Тогда сожгли Божий Храм и разрушили стену Иерусалима, сожгли все дворцы, уничтожили все, что было в нем драгоценного.","20":"А тех, кто уцелел, увели в плен в Вавилон. Там они и их дети оставались рабами до тех пор, пока не вошло в силу персидское царство –","21":"во исполнение слова Господа, произнесенного пророком Иеремией, пока не насладилась земля субботним покоем, отдыхая в запустении своем, пока не прошло семьдесят лет.","22":"В первый год правления Кира, царя персидского, во исполнение слов Господа, сказанных через Иеремию, Господь побудил Кира, царя персидского, провозгласить по всему царству и издать письменный указ:","23":"«Так говорит Кир, царь персидский. Все царства земли отдал мне Господь, Бог Небесный. И повелел Он мне построить Ему Храм в Иерусалиме, в Иудее. Те, кто принадлежит к Его народу – да пребудет с ними их Бог! – пусть идут туда»."}};
